programs.sol:
"""A partial heuristic for type/size inspection and mathematical properties.

Give the largest predictions to type-inspection names. Smaller positive
values cover size queries, string operations, and selected mathematical
'of' phrases. These families recur in strong training activations.
Some structured-object phrases and following articles get negative values.
Unrecognized tokens get zero; much contextual variation remains unmodeled.
Only the last 100 characters are retained, resetting between documents.
"""
import re

READS = ()


def operation(token, before):
    """Assign strengths to recognizable operations and property phrases."""
    word = token.strip()
    name = word.lstrip('(*._,')
    joined = token[:1].isalpha() and before[-1:].isalpha()
    if joined and name != 'attr':
        return 0.0
    if name == 'type' and word.startswith('('):
        return 6.5  # nested type inquiry
    if name == 'typeof':
        return 9.0  # type inquiry
    if name in ('sizeof', 'strlen'):
        return 4.0  # storage size
    if name == 'len' and not word.startswith('.'):
        if word.startswith('('):
            return 8.0 if before.endswith('range') else 4.5
        if token[:1].isspace() or before.endswith(('(', '=', '[', '{', '-')):
            return 4.0  # length
    if name == 'str':
        # A conversion in an expression, rather than a type annotation
        # or the beginning of a longer prose word.
        if re.search(r'(?:\bassert|\bprint|[%+])$', before.rstrip()):
            return 4.0
        if re.search(r'(?:[=,(\[{]|\bin)$', before.rstrip()):
            return 2.7
        if before.rstrip().endswith('return'):
            return 1.5
        if word.startswith('('):
            return 0.6
    if word == '+' and before.rstrip().endswith(('"', "'")):
        return 1.9  # string concatenation
    if name in ('abs', 'enumerate', 'ord'):
        return 1.6  # scalar builtin
    if name == 'isArray':
        return 6.5 if word.startswith('.') else 1.4
    if name == 'isset':
        return 7.5 if '(' in word or before.endswith('(') else 0.3
    if name in ('isinstance', 'issubclass', 'hasattr'):
        return 9.8  # type predicate
    if name in ('getItem', 'setItem') and word.startswith('.'):
        return 2.5  # named storage access
    if name == 'IsNullOrEmpty':
        return 3.7
    if name == 'unset':
        return 3.5
    if name in ('getattr', 'setattr'):
        return 3.7  # attribute builtin
    if name == 'attr' and before.endswith('.set'):
        return 10.0  # attribute patch
    if name in ('strcpy', 'strncpy', 'memcpy', 'memset', 'strerror'):
        return 2.5  # C memory and string builtin
    if word.startswith('_') and re.search(r'\bis$', before):
        if name in ('array', 'string', 'object'):
            return 3.3  # PHP type predicate
        if name in ('int', 'bool', 'float', 'null'):
            return 1.2  # PHP scalar predicate
    if name == 'undefined':
        return 1.1  # undefined value
    if name in ('defined', 'exists', 'empty'):
        return 0.25  # existence
    if name == 'append':
        if word.startswith('.'):
            return 0.35  # method append
        if token[:1].isspace() or word.startswith('('):
            return 1.7  # append builtin
    if word in ('!(', '(!', '(!(', '!(('):
        return 0.7  # negation
    if word == 'for' and re.search(r'\b[Ss]olv(?:e|ing)$', before):
        return 2.0  # solving for
    if word == 'in' and re.search(r'(?:^|\n|\\n)[ \t]*for \w+(?:, *\w+)*$', before):
        return 1.3  # loop membership
    if word == 'of':
        m = re.search(r'([a-zA-Z]+)$', before)
        prev = m[1].lower() if m else ''
        singular = prev[:-1] if prev.endswith('s') else prev
        if singular == 'factor' and re.search(r'\bprime factors?$', before):
            return 5.5  # prime factorization
        if prev in ('digit', 'digits', 'bits'):
            return 4.2  # numeric representation
        if singular in ('coordinate', 'factor', 'exponent', 'coefficient',
                        'determinant', 'divisor', 'cardinality'):
            return 2.3  # mathematical descriptor
        if singular in ('value', 'power', 'length', 'width', 'height',
                        'dimension', 'degree', 'index', 'size', 'derivative',
                        'denominator', 'eigenvalue', 'magnitude', 'deviation'):
            return 0.7  # numeric property
        if singular in ('sequence', 'matrix', 'vector', 'array', 'tuple', 'string',
                        'list', 'system', 'function', 'pair', 'product', 'field'):
            return -0.35  # structured object
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = operation(token, before)
    if token == ' the':
        if re.search(r'\b(of|by|using|compute|find|contains|equals) $', before + ' '):
            value = -0.10
    return (doc, (before + token)[-100:]), value

programs.haiku:
"""Fires on the head of a built-in call in code, mostly type tests such as isinstance(...)
and typeof, weaker for length and string functions, plus a few 'in' and 'of' contexts."""
READS = ()
TYPE_TESTS = {"isinstance", "hasattr", "typeof", "isset"}
LENGTHS = {"len", "strlen", "sizeof"}
ATTRS = {"getattr", "attr"}
OTHER_CODE = {"ord", "abs", "strcpy", "append"}
OF_NOUNS = {"factors", "factor", "coordinates", "values", "powers", "derivative", "degree", "domain"}
def step(carry, prefix, upstream):
    toks = [t.strip() for t in prefix.token_strings]
    word = toks[-1].strip("(*.[{=+&!:")
    prev = toks[-2] if len(toks) > 1 else ""
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.35
    if toks[-1] == "··":
        return None, 1.6
    if word in TYPE_TESTS:
        return None, 10.0
    if word in LENGTHS:
        return None, 4.0
    if word in ATTRS:
        return None, 3.0
    if word in OTHER_CODE:
        return None, 1.5
    if word == "str" and prev not in ('"', "'"):
        return None, 2.0
    if toks[-1] == "in" and len(toks) > 2 and toks[-3] == "for":
        return None, 1.0
    if toks[-1] == "of" and prev in OF_NOUNS:
        return None, 3.0
    if toks[-1] == "+" and prev[-1:] in ('"', "'"):
        return None, 2.0
    return None, 0.0

programs.sol:
"""A document-onset response, persisting through identical opening tokens.

Predict nearly zero after the opening run. For that run, estimate the response
from spelling: capitals (especially several together), digits, punctuation,
whitespace, source-code openings, and a few grammatical word classes. Constants
are approximate amplitudes from training examples, not exact lexical values.
"""
import regex

READS = ()
DIGITS = (8.4, 3.9, 7.8, 3.8, 4.4, 3.5, 6.0, 4.1, 5.1, 1.1)


def initial_value(text):
    word = text.strip()
    if text.startswith('<|'):
        return -0.3
    if len(word) == 1 and word in '0123456789':
        return DIGITS[int(word)]
    if word.isupper():
        letters = sum(c.isalpha() for c in word)
        if letters == 1:
            return 6.4
        if letters == 2:
            return 13.5
        if not any(c in 'AEIOU' for c in word):
            return 10.0
        return 17.0 if text.startswith(' ') else 22.0
    if not word:
        if text.count('\n') >= 2:
            return 0.7
        if '\n' in text:
            return 3.6 if text == '\n' else 1.4
        return 4.0
    if word.startswith('#') and len(word) > 1 and word[1:].isalpha():
        if word in ('#ifndef', '#ifdef', '#define'):
            return 25.0
        return 9.0
    if word.startswith(('/*', '//')):
        return 7.0
    if not any(c.isalnum() for c in word):
        if text.count('\n') >= 2:
            return 1.0
        if word in (':', '|', '/', '-', '(', '['):
            return 1.0
        if word in ('"', "'", ')', '*'):
            return 5.0
        return 3.3
    if word in ('import', 'package'):
        return 4.5
    if word in ('What', 'When', 'Where', 'Why', 'How'):
        return 5.0
    if word.lower() in ('the', 'and', 'of', 'to', 'in', 'with', 'for',
                         'that', 'they', 'you', 'from', 'at', 'or'):
        return -0.5
    if word.lower() == 'on':
        return -3.0
    if word.islower():
        if len(word) == 1:
            return 5.5 if word == 'a' else 3.6
        return 0.2 if text.startswith(' ') else 1.1
    if word.istitle():
        return 1.0 if len(word) <= 3 else 2.1
    if regex.search(r'\p{Script=Katakana}', word):
        return 7.0 if len(word) <= 2 else 3.5
    if regex.fullmatch(r'\p{Script=Han}+', word):
        return 0.6 if len(word) == 1 else 1.4
    if regex.fullmatch(r'\p{Script=Hangul}', word):
        return 3.0
    return 1.5


def step(carry, prefix, upstream):
    first = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    text = prefix.token_strings[-1]
    if first:
        return (prefix.token_bytes[-1], True), initial_value(text)
    initial, repeating = carry
    repeating = repeating and prefix.token_bytes[-1] == initial
    value = initial_value(text) if repeating else 0.0
    return (initial, repeating), value

"""Approximate responses to short written NG pieces.

Standalone thing/Thing is positive, weakened after quantifiers or selectors.
Other short -ing spellings are positive at word starts (less so for common
English words) or after tiny/consonantal stems. Longer attached stems usually
make -ing/-ung negative. Short Katakana ング endings are negative too.
A separate rule covers repeated middle dots. Everything else predicts zero.
Carries up to 30 letters of the current word, resetting between documents.
This is a spelling-based approximation, not a grammatical parser.
"""
import re
from wordfreq import zipf_frequency

READS = ()
QUANTIFIERS = {'one', 'any', 'some', 'every', 'many', 'no', 'such',
               'this', 'that', 'another'}
SELECTORS = {'same', 'only', 'first', 'whole', 'other', 'next', 'entire',
             'last'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.strip()
    lower = s.lower()
    continuing = bool(word) and token[:1].isalpha()
    value = 0.0
    if lower == 'thing':
        if continuing and token != 'Thing':
            value = -0.2
        elif word.lower() in QUANTIFIERS:
            value = 0.4
        elif word.lower() in SELECTORS:
            value = 1.25
        else:
            if token[:1].isspace():
                value = 2.65
            else:
                value = 2.85 if token == 'Thing' else 4.0
    elif lower == 'ng':
        if any(c in word.lower() for c in 'äöü'):
            value = 3.5
        elif word.isascii():
            value = 2.0 if 0 < len(word) <= 2 else 0.8
        else:
            value = 0.05
    elif re.fullmatch(r'[bdfghjklmnpqrstvwxz]{0,2}ing', s):
        if not continuing:
            rarity = 5.5 - zipf_frequency(s, 'en')
            value = min(2.5, max(0.1, 1.2 * rarity))
            if not token[:1].isspace():
                value = 2.8
        elif lower == 'ring':
            value = 1.0
        elif not re.search('[aeiouyäöü]', word, re.I):
            value = 3.5
        elif lower == 'ing' and len(word) <= 2:
            value = 3.0
        else:
            value = -0.25
    elif token in ('ings', 'ung', 'ungs', 'ungen'):
        short_stem = len(word) <= 2 or not re.search(
            '[aeiouyäöü]', word, re.I)
        value = 3.0 if short_stem else -0.2
        if token.startswith('u'):
            value *= 0.35
    elif token == ' eing':
        value = 1.7
    elif token == 'ingen':
        value = 2.0
    elif re.fullmatch(r'\s*[bcdfghjklmnpqrstvwxyz]{0,2}[aeouäöü]ng',
                      token, re.I):
        value = 0.25
    elif token.endswith('ング') and len(token) <= 3:
        value = -1.5
    elif len(token) >= 2 and set(token) == {'·'}:
        value = 2.35
    tail = re.search(r'[^\W\d_]+$', word + token)
    word = tail.group()[-30:] if tail else ''
    return (doc, word), value

"""Recognize the beginning of a mathematical function's argument.

Parentheses attached to conventional function symbols, trig/log functions or
Greek-named functions get the largest response; ordinary code calls are weaker.
The rules also recognize TeX formatting, square-bracket arguments, and a small
response to variables after coefficients, norm bars, or an opening delimiter.
Whitespace and quoted/empty arguments weaken the function-call reading.
Only a short suffix of the current document is retained.
"""
import regex as re
import unicodedata

READS = ()
MATH_FUNCTIONS = set('''sin cos tan cot sec csc sinh cosh tanh arcsin arccos
arctan asin acos atan log ln exp gcd lcm det dim rank ker arg deg tr diag
lim sup inf re im var cov erf'''.split())
NUMERIC_FUNCTIONS = set('abs min max pow round floor ceil mod sum'.split())
GREEK_NAMES = set('''alpha beta gamma delta epsilon zeta eta theta iota kappa
lambda mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega
varepsilon vartheta varphi varrho varsigma'''.split())
SIZES = {'left', 'big', 'Big', 'bigl', 'Bigl', 'bigg', 'Bigg', 'biggl'}


SUBSCRIPT = re.compile(r'_(?:\{[^{}]*\}|[A-Za-z0-9])$')
FUNCTION_NAME = re.compile(
    r'([A-Za-z_][A-Za-z_0-9]*|\p{Script=Greek})\}*$'
)
MATH_QUALIFIER = re.compile(r'(?:math|Math|np|numpy|cmath)\.$')
COEFFICIENT = re.compile(r'(?<!\w)[1-9]\d{0,2}$')


def function_kind(text):
    text = text.rstrip("′'’")
    # Strip a simple subscript and recognize names inside TeX font braces.
    text = SUBSCRIPT.sub('', text)
    m = FUNCTION_NAME.search(text)
    if not m:
        return 'formatted' if text.endswith('}') else 'other'
    name = m[1]
    if m.start() and text[m.start()-1] == '.':
        if not MATH_QUALIFIER.search(text[:m.start()]):
            return 'identifier'
    if name in SIZES and m.start() and text[m.start()-1] == '\\':
        return function_kind(text[:m.start()-1])
    lower = name.lower()
    if name == 'E':
        return 'expectation'
    if name in {'P', 'p', 'Pr', 'Prob'}:
        return 'probability'
    if name in set('fghFGH'):
        return 'function letter'
    if lower in MATH_FUNCTIONS:
        return 'math function'
    if lower == 'sqrt':
        return 'square root'
    if lower in NUMERIC_FUNCTIONS:
        return 'numeric function'
    if lower in GREEK_NAMES or 'GREEK' in unicodedata.name(name[0], ''):
        return 'Greek function'
    if name in {'O', 'o'}:
        return 'asymptotic bound'
    if len(name) == 1:
        return 'other letter'
    if name.isupper():
        return 'uppercase function'
    return 'identifier'


VALUES = {
    'other': 0.0,
    'formatted': 2.0,
    'expectation': 2.5,
    'probability': 4.0,
    'function letter': 3.6,
    'math function': 3.5,
    'square root': 1.7,
    'numeric function': 1.4,
    'Greek function': 3.3,
    'asymptotic bound': 2.3,
    'other letter': 2.2,
    'uppercase function': 0.9,
    'identifier': 0.25,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', 0.0
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    stripped = token.lstrip()
    kind = function_kind(tail.rstrip())
    strength = VALUES[kind]
    value = -0.005
    opener = stripped[:1]
    if stripped.startswith('}('):
        opener = '('
        strength = VALUES[function_kind(tail + '}')]
    if opener in {'(', '['}:
        value = strength
        if opener == '[' and kind not in {'expectation', 'probability',
                                         'formatted', 'math function'}:
            value *= 0.2
        if stripped == '(':
            value *= 0.8 if kind == 'other letter' else 1.22
        elif opener == '(':
            value *= 0.88
        rest = stripped[1:]
        if rest.startswith((')', ']', '"', "'", '`', '\\"')):
            value = 0.12 if rest.startswith((')', ']')) else 0.05
        if token != stripped:
            value *= 0.22 if strength > 1 else 0.04
        if tail[-1:].isspace():
            value *= 0.08
    elif token in SIZES and tail.endswith('\\'):
        value = 0.15 + 0.6 * VALUES[function_kind(tail[:-1].rstrip())]
    elif token.isdigit() and tail.endswith(('(', '[')):
        value = 0.24 * max(0, previous)
    elif len(stripped) == 1 and stripped.isalpha():
        greek = 'GREEK' in unicodedata.name(stripped, '')
        if stripped.isascii() or greek:
            if token == stripped and COEFFICIENT.search(tail):
                value = 0.65 if stripped in 'xyz' else 0.3
            elif kind == 'math function':
                value = 0.85 if greek else 0.45
            elif tail.endswith(('(', '[')):
                value = 0.18 * max(0, previous) + (0.6 if greek else 0.08)
            elif token == stripped and tail.endswith('|'):
                value = 2.2 if tail.endswith('||') else 1.3
    return (doc, (tail + token)[-120:], value), float(value)

"""Approximate a source-layout feature, leaving ordinary text at zero.
Training examples show positive two/three-space line-number gutters and
negative source-comment banners. The program tracks the preceding line's
number-and-tab format, space-run length, and possible header openers near
a document start or code fence. Comment-marker responses fade with age.
This is a partial heuristic: lexical variation and header ambiguities remain.
State resets at document changes and after end-of-text markers.
"""
import math
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', False, 0, -1, '', False)
    _, line, numbered, age, header_age, tail, reset = carry
    if reset:
        line, numbered, age, header_age, tail = '', False, 0, -1, ''
    s = prefix.token_strings[-1]
    bare = s.strip()
    line_start = not line
    indented = not line.strip()
    fence = bool(re.search(r'```\w*\s*$', tail))
    opener = s.startswith(('/*', '//', '#!')) or s == '#'
    if opener and (age < 3 or fence):
        header_age = 0

    value = 0.0
    if s and s == ' ' * len(s):
        n = len(s)
        if line_start and n <= 6:
            if numbered:
                value = (0, .29, .56, .42, .23, .10, .06)[n]
            else:
                value = (0, .14, .32, .14, .06, .06, .06)[n]
                if age < 5 and n >= 2:
                    value = .10 if n < 4 else -.10
        elif n in (2, 3):
            value = .14 if n == 2 else .116
        elif n == 1 and indented:
            value = -.02
        elif 4 <= n <= 6:
            value = .025

    # Guess comment leaders from line layout and a recent possible header.
    if indented or fence:
        decay = math.exp(-max(header_age, 0) / 55)
        if s.startswith('/*'):
            value = (-1.6 if '\n' in s else -2.5) if header_age == 0 else -.15
        elif bare and set(bare) <= {'*'} and header_age >= 0:
            value = -3.5 * decay
        elif s.startswith('//') and header_age >= 0:
            value = (-6.5 if '\n' in s else -1.2) * decay
        elif s.startswith('#') and header_age >= 0:
            value = (-.3 if header_age == 0 else -1.4 * decay)
        elif bare == '*' and '\n' in s:
            value = -.35
    elif bare == '*' and '\n' in s:
        value = -.5

    if '\n' in s:
        parts = (line + s).split('\n')
        numbered = bool(re.match(r'^ *\d+\t', parts[-2]))
        line = parts[-1]
    else:
        line = (line + s)[-500:]
    tail = (tail + s)[-100:]
    next_header_age = header_age + 1 if header_age >= 0 else -1
    state = (doc, line, numbered, age + 1, next_header_age, tail,
             s == '<|endoftext|>')
    return state, float(value)

r"""Positive pulses for date-like numeric prefixes; negative for mapping keys.

The strongest numeric cases are the beginnings 19 and 20 in prose.
Decimal fractions and code-like contexts suppress them. Field separators
in objects/JSON have the opposite sign; ordinary prose colons do not.
Smaller rules cover 30/31, year suffixes, zero padding, and the hex
starts \xc2/\xe2. Repeated middle-dot leaders also receive a positive
pulse. These are surface-text heuristics, not a full parser.
A 512-character tail is reset at document boundaries.
"""
import re
import calendar
import regex

READS = ()
MONTHS = {s.lower() for s in calendar.month_name if s}
ABBREVIATIONS = {s.lower() for s in calendar.month_abbr if s}
MONTH_CONTEXT = re.compile(r'\b(?:' + '|'.join(MONTHS) + r')\b', re.I)
DATE_LINKS = {'in', 'since', 'until', 'during', 'before', 'after', 'from',
              'born', 'year', 'years', 'the'}


def date_prefix(before, nineteen):
    """Estimate how much the numeral looks like a date rather than arithmetic."""
    b = before.rstrip()
    line = before.rsplit('\n', 1)[-1]
    if re.search(r'\n[ \t]{2,}$', before):
        return 0.05
    if re.search(r'[0-9]:\s*$', before):
        return 0.0
    if re.search(r'\[[^\[\]]*$|[A-Za-z_]\($', before):
        return 0.1
    if re.search(r'[0-9][.,]$', before):
        return -0.25
    if not b:
        return 0.65
    if not line.strip():
        if regex.search(r'\p{Script=Han}', before[-12:]):
            return 1.4
        return 0.65 if nineteen else 0.5
    if re.search(r'[=+*<>$£€]$', b):
        return 0.05
    if MONTH_CONTEXT.search(before[-35:]):
        return 1.6
    if re.search(r'\b(?:than|equals|minus|plus)\s*$', before.lower()):
        return 0.0
    if re.search(r'[=+*]|\b(?:const|let|return|int|float)\b', line[-70:]):
        return 0.15
    if regex.search(r'\p{Script=Han}', before[-12:]):
        return 1.45
    word = re.search(r'([A-Za-z]+)\s*$', before)
    if word:
        w = word[1].lower()
        if before[-1].isspace():
            if w in MONTHS or w in DATE_LINKS:
                return 1.55
            if w in ABBREVIATIONS:
                return 1.1
            # In general prose, 19 is more reliably a year than 20.
            return 0.95 if nineteen else 0.7
        return 0.35
    if b.endswith('('):
        return 1.25
    if b.endswith(('-', '–', '—', '/')):
        return 0.7
    if b.endswith(','):
        return 1.15 if before[-1].isspace() else 0.45
    if before[-1].isspace():
        return 0.95
    return 0.45


def object_context(text):
    # Find the enclosing delimiter, skipping completed brackets/parentheses.
    depth = 0
    for ch in reversed(text):
        if ch in ')}]':
            depth += 1
        elif ch in '({[':
            if depth:
                depth -= 1
            else:
                return ch == '{'
    return False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        m = re.search(r'[0-9]+$', text)
        number = m[0] if m else ''
        if (number, token) in (('1', '9'), ('2', '0')):
            value = date_prefix(text[:m.start()], token == '9')
            if token == '9':
                value += 0.15
        elif number.endswith('3') and token in '01':
            value = 0.5 if token == '0' else 0.35
        elif number.endswith('2') and token == '0':
            value = -0.3
        elif number == '20' and token in '12':
            value = -0.2
        elif number.endswith('000') and token == '0':
            value = 0.25
        elif token == '2' and re.search(r'\\x[ce]$', text):
            value = 0.7
    elif len(token) >= 2 and not token.strip('·'):
        value = 1.39
    elif token in ('\":', "':", '\\\":'):
        quote = "'" if token == "':" else '"'
        k = text.rfind(quote)
        key = text[k+1:]
        lead = text[:k].replace('\\n', '\n').rstrip().rstrip('\\').rstrip()
        if k >= 0 and lead.endswith(('{', ',')):
            value = -1.5
            if lead.endswith('{'):
                value = -2.25 if not lead[:-1].rstrip().endswith(':') else -1.7
            value += min(0.8, 0.35 * sum(c in '_-:/' for c in key))
            if regex.search(r'\p{Script=Han}', key):
                value *= 0.5
    elif token == ':':
        m = re.search(r'[\w$]+$', text)
        if m:
            lead = text[:m.start()].replace('\\n', '\n').rstrip()
            # Source-code listings may put a line number before the field.
            lead = re.sub(r'\n\s*[0-9]+\s*$', '', lead).rstrip()
            # A field follows a brace/comma, not a function's opening parenthesis.
            if lead.endswith(('{', ',')) and object_context(lead):
                value = -1.6
                if re.search(r'=\s*\{$', lead):
                    value = -2.0
    elif token.strip() == '=>' and text.rstrip().endswith(("'", '\"')):
        quote_start = text.rfind(text.rstrip()[-1], 0, len(text.rstrip()) - 1)
        lead = text[:quote_start].rstrip()
        value = -1.9 if lead.endswith('[') else -1.0
    return (doc, (text + token)[-512:]), value

"""Sparse text-pattern detector centered on 差 (difference/shortfall).

A bare 差 is strongly negative; fused compounds are weaker, as are time and
superlative phrases. Other single characters pronounced chā have a weaker
negative response, as does Japanese しか (only). Strong continuations include
Japanese し after 差, Korean 이 after 차, and certain vowels after Cyrillic ч.
There are small
rules for Thai/Persian continuations and document-initial middle-dot runs,
plus a small negative document-initial offset.  This is not a general
semantic difference detector.  A UTF-8 decoder joins split characters;
all state resets for a new document.
"""

import codecs
from functools import lru_cache

import regex
from pypinyin import Style, lazy_pinyin

READS = ()
UTF8 = codecs.getincrementaldecoder('utf-8')


@lru_cache(maxsize=4096)
def first_tone_cha(character):
    return lazy_pinyin(character, style=Style.TONE3)[0] == 'cha1'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    decoder = UTF8(errors='replace') if new_document else carry[2]
    fragmented = bool(decoder.getstate()[0])
    token = decoder.decode(prefix.token_bytes[-1])
    text = token.strip()
    only_middle_dots = text == '··' and (new_document or carry[3])
    value = -0.002
    if new_document:
        value = -0.15
        if text.isalpha():
            ascii_start = text.isascii() and (len(text) == 1 or text[0].isupper())
            value = -0.4 if ascii_start else -0.24
        elif text.isdecimal():
            value = -0.4
        elif text.startswith('<|'):
            value = -0.3

    if '差' in text:
        value = -7.9 / len(text) ** 1.5
        if text == '差':
            if fragmented:
                value = -11.5
            elif previous.endswith(('时', '時間', '时间', '最', '最大', '最小')):
                value = -4.2
            elif previous.endswith(('不', '还', '還', '没', '沒', '只', '就')):
                value = -10.3
            elif regex.search(r'\p{Hiragana}|\p{Katakana}', previous):
                value = -7.1
        elif text.startswith('相'):
            value = -6.8
        elif '异' in text or '異' in text:
            value *= 0.35
    elif text == '차':
        value = -4.1 if token.startswith(' ') else -3.3
    elif previous.strip() == '差' and text.startswith('し'):
        value = -6.0
    elif previous.strip() == '차' and text == '이':
        value = -3.0
    elif text == 'しか':  # Japanese restrictive particle, 'only'.
        value = -1.3
    elif token == text and previous.lower().endswith(('ч', 'щ')):
        if text.startswith('ай'):
            value = -2.6 if previous.strip().lower() == 'ч' else -0.9
        elif text == 'а':
            value = -1.0
        elif text == 'уть':
            value = -3.1
        elif previous.strip().lower() == 'ч':
            if text.startswith(('ел', 'ёр')):
                value = 2.2
            elif text == 'е':
                value = 0.3
    elif previous.endswith('ช') and text == 'ี':
        value = 4.5
    elif previous.endswith('چ') and text == 'ه':
        value = 1.4
    elif len(text) == 1 and regex.fullmatch(r'\p{Script=Han}', text):
        if first_tone_cha(text):
            value = -1.4
    elif only_middle_dots:
        value = -1.9

    return (doc, token, decoder, only_middle_dots), value

"""Heuristic for bibliographic punctuation and scholarly search/link labels.

Keep a short textual history, reset at document boundaries. Years, page ranges,
publication terms, author initials and repeated numeric line endings distinguish
reference formatting from ordinary prose. Emit negative pulses at its punctuation
and link labels. A document-opening title label and doubled middle dots have
separate responses. This deliberately leaves most prose variation unexplained.
"""
import re

READS = ()
YEAR = re.compile(r'\b(?:1[5-9]\d\d|20\d\d)\b')
PAGES = re.compile(r'\d+\s*[-–−]\s*\d+')
PUBLICATION = re.compile(
    r'\b(?:doi|isbn|issn|pmid|arxiv|journal|press|publishing|university|'
    r'vol|pp|proc|proceedings|bibliography|references)\b', re.I)
INITIALS = re.compile(r'\b[A-Z]\.[ ,]*(?:[A-Z]\.)?')
REFERENCE_END = re.compile(
    r'(?:\b(?:1[5-9]\d\d|20\d\d)|\d+[-–]\d+)[.)。 ]*\n')


def punctuation(s, history):
    period = s in ('.', '.(')
    line_end = '\n' in s and s.strip() in ('.', ').', '].', '.)')
    spaced_break = '\n' in s and s.isspace() and s.startswith(' ')
    bracket = s.strip() in ('[', ']')
    bullet = s.strip() in ('-', '–', '•', '·') and history.endswith('\n')
    if not (period or line_end or spaced_break or bracket or bullet):
        return 0.0

    h = history[-240:]
    tail = h.rstrip()
    if spaced_break:
        tail = tail.rstrip('.。) ')
    line = tail.rsplit('\n', 1)[-1]
    number = re.search(r'\d+$', tail)
    digits = len(number[0]) if number else 0
    page_end = bool(re.search(r'\d+\s*[-–−]\s*\d+$', tail))
    years = bool(YEAR.search(h))
    pages = bool(PAGES.search(h))
    pubs = len(PUBLICATION.findall(h))
    initials = len(INITIALS.findall(h))
    line_digits = sum(c.isdigit() for c in line)
    recent_digits = sum(c.isdigit() for c in h[-80:])
    commas = line.count(',')
    prior_ends = len(REFERENCE_END.findall(history))

    if period:
        if pubs >= 2:
            if digits:
                return -2.2 if recent_digits >= 10 else (-1.5 if initials else -0.65)
            return -0.1
        if digits:
            if pubs:
                return -2.4 if page_end else -0.8
            return -0.6 if page_end else (-0.09 if digits >= 2 else -0.01)
        return 0.0

    if line_end:
        if page_end:
            if years:
                if prior_ends:
                    return -3.5
                return -2.4 if len(line) < 166 else -1.2
            return -0.7 if digits >= 3 else -0.12
        if digits >= 3:
            if pubs:
                return -2.65 if commas >= 2 else -1.0
            return -1.5 if prior_ends >= 2 else -0.23
        if pubs >= 2:
            return -1.2 if line_digits else -0.35
        return -0.09 if years else 0.0

    if bracket:
        if pubs:
            if commas >= 4:
                return -4.3 if re.search(r'\[\d+\]', history) else -2.15
            return -1.3 if pages else (-0.37 if years else 0.0)
        if initials >= 3 and recent_digits >= 8:
            return -1.25
        return -0.6 if years and commas >= 4 else 0.0

    if bullet:
        if years:
            if line_digits >= 16:
                return -3.0
            if initials:
                return -2.4
            return -0.8 if line_digits >= 4 else -0.13
        if prior_ends:
            return -1.37 if line_digits >= 2 else -0.23
        return -0.6 if digits >= 2 and recent_digits <= 20 else 0.0

    # A whitespace token following the final period of a reference.
    if digits >= 2:
        if initials:
            if years and pages:
                return -1.6
            return -0.45 if digits == 2 and not years else -0.8
        if s.count('\n') > 1:
            return -0.64 if digits >= 3 else -0.3
        return -0.46 if years else -0.14
    return -0.4 if recent_digits >= 3 and initials and line_digits >= 2 else (
        -0.1 if recent_digits >= 3 else 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    h = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    end = h[-50:] + s
    if s == '··':
        value = 2.52
    elif s == ':' and h == 'Title':
        value = -4.0
    elif re.search(r'\b(?:WorldCat|Medline)$', end, re.I):
        value = -6.4
    elif re.search(r'\b(?:Scopus|Zbl)$', end):
        value = -5.2
    elif re.search(r'(?:^|\n)PMID$', end):
        value = -4.7
    elif end.endswith(('Google Scholar', 'View Article', 'Full Text')):
        value = -4.7
    else:
        value = punctuation(s, h)
    return (doc, (h + s)[-500:]), float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 329.

What it does: almost always silent. Its job shows up on the punctuation of citation-dense
text (bibliographies, footnotes, indexes, reference lists), where entries are strings of
numbers (page numbers, years, volumes) ended by full stops and line breaks. There it goes
negative at the line breaks that begin or end an entry, and the more numbers came just
before, the more negative:
  - a dash that starts a line ("\\n-", as in list items "- 3."), strongest;
  - a blank line (" \\n\\n") right after a full stop;
  - a full stop followed by a newline (".\\n");
  - a plain full stop after numbers, weakly.
At the first token of a document, which has no context, it is mildly positive.

Program: count the tokens holding a digit among the few tokens before the current one, inside
the current document, and set the value from the token's kind and that count.
"""

READS = ()

DOC_START = 0.15          # first token of a document: mildly positive
DASH_PER_NUMBER = -1.0    # "-" opening a line: -1 per number above two in the last 6 tokens
BLANK_PER_NUMBER = -0.5   # blank line after a full stop: -0.5 per number above one in the last 4
NEWLINE_STOP_PER = -0.2   # ".\n": -0.2 per number above one in the last 6
FULL_STOP = -0.05         # "." with two or more numbers in the last 6 tokens


def _has_digit(tok):
    return any(ch.isdigit() for ch in tok)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = len(toks) - 1
    if t == 0 or docs[t] != docs[t - 1]:
        return carry, DOC_START
    tok = toks[t]
    lo = max(0, t - 6)
    while lo < t and docs[lo] != docs[t]:
        lo += 1
    numbers_6 = sum(_has_digit(x) for x in toks[lo:t])
    numbers_4 = sum(_has_digit(x) for x in toks[max(lo, t - 4) : t])
    if tok in (" \n\n", "  \n", " \n") and toks[t - 1].endswith(".") and numbers_4 >= 2:
        return carry, BLANK_PER_NUMBER * (numbers_4 - 1)
    if tok == "-" and "\n" in toks[t - 1] and numbers_6 >= 3:
        return carry, DASH_PER_NUMBER * (numbers_6 - 2)
    if tok == ".\n" and numbers_6 >= 2:
        return carry, NEWLINE_STOP_PER * (numbers_6 - 1)
    if tok == "." and numbers_6 >= 2:
        return carry, FULL_STOP
    return carry, 0.0

