"""Sparse diagnostic-word, dash, and broken-encoding responses.

'Got' is positive, strongest near expected-versus-actual diagnostics and weak
in have-got phrases. 'Found' is positive near no/not. Attached long dashes are
negative, especially after numbers; spaced ones are weakly positive. NUL bytes
are positive, stronger after letters or digits. Everything else is zero.

Only the last 180 decoded characters are retained, reset at document boundaries.
This intentionally leaves the varied multilingual word-fragment responses out.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ''
    else:
        history = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0

    if word == 'got':
        if re.search(r'expected|expecting|error|failed|assert|but\s*$',
                     history[-160:], re.I):
            value = 1.8
        elif re.search(r"(?:have|has|had|ve|s)\s*$", history[-30:], re.I):
            value = 0.04
        else:
            value = 0.35
    elif word == 'found' and re.search(r'\b(no|not)\b', history[-60:], re.I):
        value = 0.85
    elif word in ('—', '--', '.--', '.—', ')—'):
        if token.startswith(' '):
            value = 0.15 if '—' in token else 0.05
        elif history and not history[-1].isspace():
            value = -1.05 if history[-1].isdigit() else -0.5
    elif '\x00' in token:
        value = 1.8 if history and history[-1].isalnum() else 0.3

    return (doc, (history + token)[-180:]), value

"""A boundary-sensitive U feature, strongest on 'the United'.

Recognize United, U/u spellings, uint types, unsigned arithmetic endings,
and u starting a Unicode escape. Articles and digits strengthen U; uppercase
acronym continuations and math-operator contexts get weak responses. Smaller responses cover the
micro sign, Java/Android .util and the next token in U.S./United States.
Other tokens receive zero. Fine contextual variation is not reconstructed.
"""

READS = ()

# Arithmetic operators and common TeX spellings of mathematical symbols.
MATH_OPERATORS = {
    '=', '+', '-', '*', '/', '∂', '∇',
    'partial', 'cdot', 'Vert',
}
# These instruction stems take a suffix u to indicate unsigned arithmetic.
UNSIGNED_OPS = {
    'div', 'rem', 'mod',
    'ge', 'gt', 'le', 'lt', 'slt', 'sge',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    prev_word = previous.strip().lower()
    last = previous[-1:]
    spaced = token[:1].isspace()
    value = 0.0

    if word.lower() == 'united':
        if word == 'United':
            value = 6.2 if spaced else 5.3
            if spaced and prev_word == 'the':
                value = 9.3
        elif word.isupper():
            value = 5.0
        else:
            value = 3.5 if not last.isalnum() else 2.0
            if prev_word == 'the':
                value = 5.8
    elif word == 'U':
        if spaced:
            value = 2.3
            if prev_word == 'the':
                value = 4.4
            elif prev_word in ('a', 'an'):
                value = 3.4
            elif last.isdigit():
                value = 3.8
            elif previous.strip().isupper() and len(previous.strip()) == 1:
                value = 1.0
        else:
            value = 0.15 if last.isupper() else 1.7
            if last.isdigit():
                value = 2.5
    elif word == 'u':
        value = 1.5 if spaced else (0.0 if last.isalpha() else 1.0)
        if prev_word == 'the':
            value = 4.5
        if not spaced and last.isdigit():
            value = 2.4
        if previous.endswith('\\'):
            value = 6.7
        elif not spaced and prev_word == 'mul':
            value = 3.4
        elif not spaced and prev_word in UNSIGNED_OPS:
            value = 1.1
    elif word.lstrip('_<(.,:/').lower() == 'uint':
        value = 4.0
    elif word.lstrip('_<.-/').lower() == 'u':
        value = 3.0
    elif word == 'µ':
        value = 1.7 if last.isdigit() else 0.3
    elif previous.strip() in ('United', 'united') and word.lower() == 'states':
        value = 0.5
    elif previous.strip() == 'U' and word in ('.S', 'S'):
        value = 0.9
    elif word == '.util' and prev_word in ('java', 'android'):
        value = 2.1

    if word in ('U', 'u') and previous.strip() in MATH_OPERATORS:
        value = 0.25

    return (doc, token), value

"""Detect FS/file-system spellings, with weaker scientific-suffix echoes.

The main negative response is to FS initials, BFS/DFS, and 'file system'.
Case, token boundaries, and word frequency distinguish abbreviations from
ordinary word endings. Literal oph/ophys and related fragments get smaller
negative values. All predictions are attenuated: spelling alone is only a
partial predictor. State is recent text, reset at document boundaries.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def commonness(word):
    return max(zipf_frequency(word.lower(), language)
               for language in ('en', 'de', 'nl', 'fr'))


def predict(token, before):
    t = token.lower()
    fragment = t.lstrip(' \t\r\n./_(-')
    match = re.search(r'[A-Za-z]+$', before)
    previous = match.group() if match else ''
    spaced = token[:1].isspace()

    # Full name, including camelCase and underscore-separated forms.
    if re.search(r'file[ _-]*system\Z', (before + t).lower()):
        if 'file' in t:
            return -3.5
        return -5.0 if t.startswith('_') else -7.0
    if fragment in ('system', 'systems'):
        return 0.18

    if fragment in ('bfs', 'dfs'):
        if token.strip().islower():
            return -3.2
        return -6.3 if spaced else -8.5

    # FS, and network/virtual/Unix filesystem initials and Btrfs fragments.
    if re.fullmatch(r'(?:[aneuv]|tr)?fs', fragment):
        if fragment != 'fs':
            if previous and commonness(previous + token) > 2.5:
                return -0.5
            return -4.8 if spaced or token.isupper() else -2.5
        if spaced:
            return -4.4 if token.strip().islower() else -2.9
        if token[:1] in './_(':
            return -3.8
        if token.isupper():
            return -8.5 if previous.isupper() else -5.0
        if token == 'Fs' and previous.isupper():
            return -1.0  # an acronym's plural F+s
        # Short prefixes form initials (N+FS, S+FS), not ordinary plurals.
        if previous and len(previous) <= 2:
            return -8.0
        if token == 'Fs' and not previous and before[-1:] not in '.{':
            return -3.0
        frequency = commonness(previous + token) if previous else 0
        if frequency > 2.8:
            return -1.0
        if frequency > 1.5:
            return -3.0
        # Memory-backed, remote and mapping-based filesystem names.
        if previous.lower().endswith(('mem', 'ftp', 'http', 'map', 'regexp')):
            return -10.0
        return -5.8

    if fragment == 'ifs' and token.isupper():
        return -4.5
    if fragment == 'ofs':
        frequency = zipf_frequency((previous + token).lower(), 'en')
        return -0.5 if frequency > 1.5 else -6.0

    # Transliteration also catches some non-Latin f+s spellings.
    left = anyascii(before[-12:]).lower()
    right = anyascii(token).lower()
    if left.endswith('f') and right == 's':
        if not token.isascii() and token.isupper():
            return -7.5
        if len(previous) == 1:
            # A subscript-like F+s after a ratio is usually a variable.
            return -2.0 if before.endswith(('/F', '/f')) else -7.5
        return 0.0
    if left.endswith('f') and re.match(r'^(?:[zy]|[aeiou][szy]|s.)', right):
        return -1.7

    # Literal Greek-derived scientific fragments and the -ify suffix.
    if fragment in ('oph', 'ophys'):
        strength = 1.8 if fragment == 'oph' else 4.5
        if previous.lower().endswith(('bi', 'ge', 'fluor')):
            strength += 2.2
        return -strength
    if left.endswith('ph') and (right == 'y' or right.startswith('ys')):
        return -3.5 if len(right) <= 4 else -0.8
    if fragment in ('ops', 'opy', 'omy') and not spaced:
        return -3.5 if token.isupper() else -1.1
    if fragment in ('ify', 'fy'):
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.65 * predict(token, before)
    return (doc, (before + token)[-80:]), value

"""A sparse approximation to spelling-sensitive European inflections.

Completed words and distinctive accents provide a fading language estimate.
Hungarian particles/stem fragments and Czech 'i' receive positive values;
Lithuanian case endings and several Cyrillic/Greek continuations receive
negative values. Language gating distinguishes these spellings from English.
Repeated middle dots have a positive response.
This captures selected responses, not every token-specific language effect.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('hu', 'lt', 'fi', 'cs')
OTHERS = ('en', 'de', 'fr', 'es', 'it', 'pt', 'pl', 'tr', 'nl', 'ro')


@lru_cache(maxsize=16000)
def language_evidence(word):
    if len(word) < 2 or not word.isalpha():
        return (0.,) * 4
    baseline = max(zipf_frequency(word, l) for l in OTHERS)
    frequencies = [zipf_frequency(word, l) for l in LANGUAGES]
    frequencies[3] = max(frequencies[3], zipf_frequency(word, 'sk'))
    best = max(frequencies)
    evidence = []
    for i, frequency in enumerate(frequencies):
        competitor = max(baseline, max(frequencies[:i] + frequencies[i+1:]))
        margin = max(frequency - competitor - .6, 0.)
        evidence.append(margin if frequency == best and frequency > 3 else 0.)
    return tuple(evidence)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
