            value += 4.44
        if s == 'is':
            value += 1.13
        if t == 'd':
            value += 2.58
        if t == 'j':
            value += 1.75
        if len(t) > 1 and t.isalpha() and t.endswith('d'):
            value += .83
        if t == 'vis':  # fragment of visel, "bear/carry"
            value += 3.33
        if t in ('test', 'has'):  # body; belly
            value += 1.84
        if t in ('ni', 'de'):  # infinitive ending; adversative conjunction
            value += 1.46
        if t == 'í':  # long close front vowel
            value += 1.19
        if t in ('fog', 'mind', 'ellen'):  # auxiliary; all; against
            value += 1.29
        if t in ('jon', 'jen'):  # subjunctive/imperative endings
