"""A local lexical approximation: additions and intensifiers after auxiliaries.

'Even' responds most after negation, possibility words and modals; 'also'
and quantified alternatives respond more weakly. 'Well' changes sign in
'as well' and modal phrases. Ordinary 'right' is negative, unlike TeX's
closing command. Smaller rules cover 'wrong', 'depend' and modal 'just'.
Greek omega (and weaker eta/sigma) and repeated middle dots have separate
negative responses. State is the preceding token and 120 bytes of history,
reset at each document; other tokens normally return zero.
"""
import re
import unicodedata

READS = ()
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'being', "'m", "'re", '’re'}
HAVE = {'have', 'has', 'had'}
MODALS = {'can', 'could', 'will', 'would', 'should', 'may', 'might', 'must'}
PLURAL_QUANTIFIERS = {'many', 'several', 'numerous', 'few'}
NUMBER_WORDS = {'two', 'three', 'four', 'five', 'six', 'seven', 'eight',
                'nine', 'ten', 'hundred', 'thousand'}


def response(s, previous, history):
    w = s.strip().lower()
    p = previous.strip().strip('—-').lower()
    negative = p in {'not', 'never', 'cannot', 'hardly', 'barely'}
    contracted_not = p.endswith(("'t", '’t')) or p in {
        'dont', 'didnt', 'cant', 'wont'}

    if s and set(s) == {'·'} and len(s) >= 2:
        return -2.85
    greek_neighbor = history and 'GREEK' in unicodedata.name(history[-1], '')
    if w in {'η', 'σ'} and greek_neighbor:
        return -0.8 if w == 'η' else -0.4
    if w == 'Ω' and sum('GREEK' in unicodedata.name(c, '')
                        for c in history[-12:]) > 3:
        return -5.5
    if w in {'ω', 'ώ', 'ῶ'}:
        if w != 'ω':
            return -4.5 if w == 'ῶ' else -6.0
        if greek_neighbor:
            return -7.8
        return 0.0
    if s == 'right' and history.endswith('\\'):
        return 3.7 if previous == '\\' else 2.9
    if s == 'end' and history.endswith('\\'):
        return 0.65
    if s == 'right':  # unspaced identifiers are not the English word
        return 0.0

    if w == 'even':
        if contracted_not:
            return 6.1
        if negative:
            return 4.35
        if p in {'maybe', 'perhaps', 'possibly'}:
            return 5.4
        if p in {'may', 'might'}:
            return 6.1
        if p in {'can', 'could'}:
            return 3.9
        if p in {'will', 'would', 'should'}:
            return 2.6
        if p == 'or':
            return 3.7
        if p == 'and':
            return 2.2
        if p in HAVE or p in {"'ve", '’ve', 'are', 'was', 'were'}:
            return 2.1
        if p in {'i', 'we', 'you', 'he', 'she', 'they', 'it', 'there'}:
            return 2.0
        return 0.25
    if w == 'well':
        if p == 'as':
            return 3.7 if history.lower().endswith(('might as', 'may as')) else 1.25
        if p in {'may', 'might'}:
            return 3.1
        if p == 'could':
            return 1.7
        if p == 'very':
            return 4.8 if any(history.lower().endswith(m + ' very')
                              for m in MODALS) else 0.0
        if p == 'been':
            return -4.0
        if p in BE or negative or p in {'and', 'how', 'doing'}:
            return -2.1
        if p in {'the', 'a', 'each', 'most'}:
            return -0.4
        return -1.1
    if w == 'wrong':
        if p in {'go', 'going', 'gone', 'something', 'anything', 'nothing', 'thing'}:
            return -1.9
        return -0.25
    if w == 'right':
        if p in {'the', 'a', 'his', 'her', 'my', 'your', 'their', 'its', 'own'}:
            return -0.2
        if p in BE or p in {"'s", '’s', 'exactly', 'it', 'that', 'sounds'}:
            return -2.0
        if re.search(r'\b(get|got|getting|do|did|doing|done|make|made|happens?)'
                     r'\b[^.!?\n]{0,25}$', history.lower()):
            return -2.4
        return -0.75
    if w in {'depend', 'depends', 'depending'}:
        if p in {'will', 'would'}:
            return -2.1
        if p in MODALS or p in {'it', 'really', 'only'}:
            return -1.1
        return -0.35
    if w == 'just':
        return 2.0 if p in {'may', 'might'} else (0.4 if p in MODALS else 0.0)
    if w == 'also':
        if p in {'may', 'might'}:
            return 1.25
        if p in {'can', 'could'}:
            return 0.65
        if p in {'will', 'would', 'should'} or p in HAVE:
            return 0.3
        return 0.0
    if w in {'other', 'others', 'different', 'more'}:
        if p in PLURAL_QUANTIFIERS:
            return 2.5 if w == 'others' else 1.3
        if p in NUMBER_WORDS or p.isdigit() or p == 'some':
            return 0.45
        if w == 'different' and p in BE:
            return -0.4
        if w == 'other' and p == 'the':
            return -0.17
        return 0.04
    if w in {'甚至', '甚至是', 'sogar', 'даже', 'même'}:
        return 4.0 if w.startswith('甚至') else 2.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history_bytes, previous = b'', ''
    else:
        _, history_bytes, previous = carry
    s = prefix.token_strings[-1]
    history = history_bytes.decode('utf-8', errors='replace')
    value = response(s, previous, history)
    history_bytes = (history_bytes + prefix.token_bytes[-1])[-120:]
    return (doc, history_bytes, s), value

