"""Layer-1 MLP down_proj component 337 (of p-82af68dd).

What it responds to: the emphatic focus words "even", "also" and "well" (and "even" in
other languages), with the size set by the word just before them, plus LaTeX "\\right"
and the Greek small omega letters ω, ώ, ῶ, which are strongly negative.

- "even" fires hard after a negation, a modal or "or": "not even", "n't even",
  "or even", "may even", "can even", "cannot even" (about +5). After "and", "I", "we",
  "it", "are", "without" it is weaker (about +2). Elsewhere, and at a sentence start,
  it is near zero.
- Translations of "even" (甚至, даже, sogar, même) fire at about +2.5 (même about +1.5).
- "also" fires after a modal: "may also", "can also" (about +1).
- "other", "others", "different", "more" after "many" ("many others") are mildly positive
  (about +1.7). "depend" and "depends" are mildly negative (about -0.7).
- "well" is positive in "as well" (+1.2), "very well" (+1) and "may well" (+3). In most
  other uses ("works well", "is well", "been well") it is negative (about -1.5).
  Sentence-initial "Well" is treated as 0.
- LaTeX "\\right" (no space, after a backslash) is positive (+3.5). A spaced " right"
  is mildly negative, most after "is/be/are/'s" (about -2).
- ω, ώ, ῶ (small omega, with or without accent) are strongly negative (about -6), and so
  is a σ right after one of them (about -3). Other omega variants are ~0.

Everything else predicts 0 (a few small effects such as "η" at -0.7 are included).
Only the current token and the previous token (in the same document) are read.
"""

import unicodedata

READS = ()


def is_greek_letter(s):
    return len(s) == 1 and unicodedata.name(s, "").startswith("GREEK")


EVEN_WORDS = {"even"}
FOREIGN_EVEN = {"甚至", "даже", "sogar", "même"}
STRONG_BEFORE_EVEN = {"not", "n't", "’t", "'t", "never", "no", "nor", "cannot", "barely",
                      "hardly", "or", "may", "might", "maybe", "perhaps", "possibly",
                      "sometimes", "can", "could"}
MID_BEFORE_EVEN = {"and", "i", "we", "they", "will", "was", "have", "without", "are", "it"}
COPULA_RIGHT = {"is", "are", "was", "were", "be", "been", "being", "am", "'s", "’s"}
OMEGAS = {"ω", "ώ", "ῶ"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev_raw = prefix.token_strings[-2] if same_doc else ""
    prev = prev_raw.strip().lower()

    if word in EVEN_WORDS:
        if prev in STRONG_BEFORE_EVEN:
            return carry, 5.0
        if prev in MID_BEFORE_EVEN:
            return carry, 2.0
        return carry, 0.5
    if word in FOREIGN_EVEN:
        return carry, 1.5 if word == "même" else 2.5
    if word in {"other", "others", "different", "more"} and prev == "many":
        return carry, 1.7
    if word in {"depend", "depends"}:
        return carry, -0.7
    if tok == "η":
        return carry, -0.7
    if word == "also":
        return carry, 1.0 if prev in {"may", "can"} else 0.0
    if word == "well":
        if tok[:1].isupper() or not tok[:1].isspace():
            return carry, 0.0  # sentence-initial "Well", or no leading space
        if prev in {"as"}:
            return carry, 1.2
        if prev in {"may", "might", "could", "can"}:
            return carry, 3.0
        if prev == "very":
            return carry, 1.0
        return carry, -1.5
    if tok == "right":  # no leading space: LaTeX \right, after a backslash
        return carry, 3.5 if prev_raw.endswith("\\") else -0.3
    if word == "right":
        return carry, -2.0 if prev in COPULA_RIGHT else -0.4
    if tok in OMEGAS:
        return carry, -7.0 if prev_raw.strip() and is_greek_letter(prev_raw.strip()) else -3.8
    if tok == "σ" and prev_raw.strip() in OMEGAS:
        return carry, -3.0  # the sigma that follows an omega, as in -ωσ-
    return carry, 0.0

