def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, last = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    low = token.lower()
    word = re.split(r'\W', previous + low)[-1][-48:]
