            value += 1.9
        if low.startswith('-brand'):
            value += 1.9
        if suffix not in ('', 's', 'ed', 'ing', 'y', 't'):
            value = 1.5
        if last == '<|endoftext|>' and suffix == '':
            value += 5.2
    elif attached and 'brand' in word:
        suffix = word.rsplit('brand', 1)[-1]
        if 'brand' not in previous:
            value = 9.2
            if suffix in ('s', 'ed', 'y'):
                value += 3.8
            elif suffix not in ('', 'ing', 't'):
                value = 4.0
            if token.isupper():
                value += 3.5
        elif len(suffix) <= 3:
            value = 7.65 if suffix in ('e', 'ing') else 3.85
            if len(suffix) > 1 and suffix not in ('e', 'ing'):
                value = 1.0
