        # Short literal br fragments, rather than most complete English words.
        if 'br' in low:
            tail = re.split(r'\W', low)[-1].rsplit('br', 1)[-1]
            value = 0.12
            if len(tail) <= 2:
                value = 1.2
                if tail:
                    value += {'a': -0.4, 'i': -0.47,
                              'o': -0.75, 'u': 0.23}.get(tail[0], 0)
                if len(tail) == 2 and tail[-1] in 'ndt':
                    value += 0.65
            if low.strip() in ('breed', 'breeds', 'breeding'):
                value += 1.1
            if low.strip() in ('brick', 'bricks'):
                value += 2.7
            if low.strip() in ('breast', 'breasts'):
                value -= 1.5
