                              'o': 0.20, 'u': 0.36}.get(tail[0], 0)
                if re.match(r'[aeiouyüöøä]+[ndtkgc]', tail):
                    value += 0.82
                if re.match(r'(?:[auøü]n|[uü]ck)', tail):
