programs.haiku:
"""Layer-1 MLP feature: superlative, ordinal and 'only' words that modify a noun after
'the' (or a possessive), e.g. 'the first', 'the only', 'the largest', 'one of the best'.
It is strongest in record-style claims, 'is/was/became the first ...', and weak in
procedural text ('the first element'). Predicts the activation in real units."""
READS = ()

# Superlatives and 'only' hit hardest: 'the only' and 'the largest' average about 5.
STRONG = {"only", "largest", "biggest", "youngest", "oldest", "longest", "earliest", "smallest"}
# Other ordinals and superlatives: 'the first', 'the most', 'the best', 'the second'.
ORDINAL_OR_SUPERLATIVE = STRONG | {
    "first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth", "ninth", "tenth",
    "last", "most", "best", "top", "leading", "main", "highest", "lowest", "greatest", "shortest",
    "latest", "nearest", "minimal", "maximum", "dominant", "ultimate", "favorite", "popular",
    "primary",
}
DETERMINERS = {"the", "its", "his", "her", "their", "my", "our", "your", "'s"}
# A copula or 'of' two words back ('was the first', 'one of the best') doubles the response.
CLAIM_WORDS = {"is", "was", "were", "are", "be", "became", "become", "remains", "of"}
BASE, STRONG_BASE, NO_DETERMINER = 1.6, 3.2, 0.25


def word_at(prefix, back):
    """The lowercased token `back` steps before the newest one, '' across a document break."""
    i = len(prefix) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    word = word_at(prefix, 0)
    if word not in ORDINAL_OR_SUPERLATIVE:
        return carry, 0.0
    if word_at(prefix, 1) not in DETERMINERS:
        return carry, NO_DETERMINER
    level = STRONG_BASE if word in STRONG else BASE
    if word_at(prefix, 2) in CLAIM_WORDS:
        level *= 2.0
    return carry, level

programs.sol:
"""A spelling feature centered on 建 (jian) and J/Y-led syllables.

建 is strongly negative, weaker in most compound words. Selected jian/yan
characters, and Korean/Vietnamese cognate syllables, also respond. Roman
`jian` is negative; e- and ang-like continuations after J/Y are positive.
The short byte history joins split UTF-8 characters; the middle byte of
a three-token spelling of 建 also responds. Documents reset the history.
Opening `import`/`<!` tokens and all-middle-dot documents have separate
fixed responses.
"""
from functools import lru_cache
from math import sqrt
import regex
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=65536)
def text(b):
    return b.decode('utf-8', 'replace')

@lru_cache(maxsize=65536)
def roman(s):
    return anyascii(s).lower()


def predict(previous, current, first, only_dots=False):
    s = text(current)
    p = text(previous)
    t = s.strip()
    if first:
        if s == 'import':
            return 2.064
        if s == '<!':
            return -5.48
