        tail = s.lstrip('\ufffd')
        t = tail if '建' in tail else text(joined)[-len(tail) - 1:]
    if '建' in t:
        n = len(t.strip())
        if n == 1:
            if p.endswith(('构', '構')):
                return -1.3
            if p.endswith(('新', '兴', '興')):
                return -4.1
            if split:
                return -5.0 if '建' in s else -8.3
            return -6.5
        if '党' in t or '黨' in t:
            return -4.2
        if t == '新建':
            return -5.1
        if '筑' in t or '築' in t or t == '构建' or t == '構建':
            return -.7
        if t.endswith('建'):
            return -1.5 / sqrt(n - 1)
        return -2.6 / sqrt(n - 1)
    if any(ch in t for ch in '剑剣劍健坚堅燕'):
        return (-4.6 if split else -2.8) / max(len(t), 1)**2
    if '键' in t or '鍵' in t:
        return -.8 if len(t) == 1 else -1.3 / sqrt(len(t)-1)
    if t.startswith('건'):
        return -2.5 / max(len(t), 1)**2
    if t == 'kiến':
        return -3.0
    if regex.search(r'\p{Script=Han}', t):
        return .002
    q = roman(s).strip()
    if q.startswith('jiang'):
        return .05
    if q.startswith('jian'):
        return -7.5 if t.startswith('Jian') else -2.8
