        if q.startswith('iang'):
            value = .3
        elif q.startswith('ian'):
            value = -2.2 if pa.endswith('uj') else -6.5
        elif q.startswith('ang'):
            value = 2.8 if q in ('ang', 'ango') else .4
        elif q.startswith(('ia', 'ean', 'oun', 'uan')):
            value = -1.5
        elif q.startswith(('an', 'ou', 'ild')):
            value = -.9
        elif q.startswith('ena'):
            value = 3.0
        elif q.startswith(('ek', 'ep', 'est')):
            value = 1.7
        elif q.startswith(('en', 'el', 'eg')):
            value = .7
        elif regex.match(r'(a[ckx]|i[ck])', q):
            value = .7
        else:
            value = 0.
        return strength * value
    if not first and q in ('ian', 'ians'):
        return .22  # the ordinary adjective/nationality suffix
    return .002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = b'' if first else carry[1]
    current = prefix.token_bytes[-1]
    only_dots = current == '··'.encode() and (first or carry[2])
    value = predict(previous, current, first, only_dots)
    return (doc, (previous + current)[-16:], only_dots), float(value)

programs.haiku:
"""Component L1 MLP down_proj #344: a 'Japanese text' detector.

It is quiet on ordinary English/code text (about 0) and lights up on Japanese:
  * kana (hiragana/katakana) are strongly positive, most of all the first kana of a run;
  * kanji (Han characters), and the byte fragments of multi-byte characters, are strongly
    positive when a kana occurred in the last ~20 tokens (Japanese context), and about 0 in
    Chinese text, which has no kana;
  * other tokens inside Japanese context get a small positive value;
  * Hangul (Korean) is moderately positive;
  * the first token of each document is mildly positive;
  * a carriage-return character (the Windows line end) is negative.
Constants are class means measured on sampled training rows (about 0.55 variance explained).
"""
import regex

READS = ()

KANA = r"[\p{Hiragana}\p{Katakana}]"
JAPANESE_WINDOW = 20  # tokens after a kana that still count as Japanese context


def step(carry, prefix, upstream):
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    since, prev_kana = (10**6, False) if new_doc else carry  # tokens since last kana
    text = prefix.token_bytes[-1].decode("utf-8", "replace")
    if regex.search(KANA, text):
        value = 0.55 if prev_kana else 1.0  # later kana of a run are weaker
        since, prev_kana = 0, True
    else:
        since, prev_kana = min(since + 1, 10**6), False
        japanese = since < JAPANESE_WINDOW
        if new_doc:
            value = 0.35
        elif regex.search(r"\p{Hangul}", text):
            value = 0.45
        elif japanese and (regex.search(r"\p{Han}", text) or "�" in text):
            value = 1.6  # kanji, or a fragment of a multi-byte character
        elif japanese and any(ord(c) > 127 for c in text):
            value = 1.1
        elif text == "\r":
            value = -0.8
        else:
            value = 0.3 if japanese else 0.0
    return (since, prev_kana), value

programs.sol:
"""Recognize formula endings and stock web-page/footer phrases.

The strongest negative signals are closing displayed formulae and navigation
labels such as line-initial 'Read More'. Embedded 'learn/read more', proof
endings, patent filing language, and a few code/table headers have positive
signals. There is a small positive bias at each document's first token;
most other text is left near zero. Only a short text tail is kept.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = '', 0
    else:
        _, tail, position = carry
    token = prefix.token_strings[-1]
    before = tail
    tail = (tail + token)[-256:]
    value = 0.14 if position == 0 else -0.001

    # The last word in a LaTeX environment closing command, not its opening.
    end = re.search(r'\\end\{([A-Za-z]+)\Z', tail)
    if end:
        name = end[1]
        lead = tail[:end.start()].rsplit('\n', 1)[-1]
        at_line = '\n' in tail[:end.start()] and not lead.strip()
        if name == 'proof':
            value = 1.5
        elif name == 'aligned':
            value = (-6.8 if not lead else -4.4) if at_line else -2.0
        elif name == 'equation':
            value = -0.45 if at_line else -0.1
        elif name in {'array', 'matrix', 'cases', 'figure'}:
            value = -1.2 if at_line else -0.35

    # Read/view/continue links are different from 'read more' in a sentence.
    link = re.search(
        r'(?<![A-Za-z])(Read|read|View|view|Learn|learn|Continue|continue)'
        r' (More|more|Reading|reading|Online)\Z', tail
    )
    if link:
        verb, noun = link.groups()
        lead = tail[:link.start()].rsplit('\n', 1)[-1]
        line_start = not lead.strip()
        if verb.lower() == 'view':
            value = -5.0 if noun == 'More' and line_start else -1.8
        elif verb.lower() == 'continue':
            value = -2.5 if line_start and noun == 'Reading' else -0.85
        elif verb == 'Read' and (line_start or (lead and lead[-1] in '.!')):
            strength = -4.0 if line_start else -2.3
            value = strength if noun == 'More' else -1.3
        elif noun == 'Online':
            value = -1.4
        elif noun == 'More':
            if verb.lower() == 'read':
                value = -1.3
            else:
                value = -0.6 if line_start else 0.65
        else:
            value = 0.55

    # Other compact website controls and closing boilerplate.
    for phrase, strength in (
        ('View All', -2.5), ('View Profile', -2.5), ('View Full', -1.6),
        ('Related Topics', -2.8), ('Show Tags', -0.5),
        ('Leave a Reply', -1.7), ('More From', -2.2), ('Read Answer', 2.0),
        ('CrossRef', -1.2), ('[PubMed', -0.8),
        ('firstname.lastname', -1.65),
        ('IN THE SOFTWARE', -1.6), ('All Rights Reserved', -1.2),
        ('effective filing', 5.3), ('DISTRICT COURT', 1.8),
        ('scientificreports', 1.8), ('online calculator', 1.3),
        ('See also', -0.4), ('double quote', 0.6), ('find out more', 0.7),
        ('Additional file', 0.9), ('Signed-off', 2.5),
        ('Читайте также', -2.8), ('参考文献', -0.8), ('查看更多', -1.8),
        ('免费阅读', 2.0), ('在线阅读', 1.0), ('延伸閱讀', 0.8), ('最新章节', 1.7),
    ):
        if tail.endswith(phrase) and token and not before.endswith(phrase):
            value = strength

    if tail.endswith('limitations under the License'):
        line = tail.rsplit('\n', 1)[-1]
        value = -1.25 if '*' in line or '//' in line else -0.15

    if tail.endswith(('</ref', '&lt;/ref')):
        value = 1.3

    # A short remaining piece of a long table ruling, and source-file headers.
    if token == '__' and before.endswith('_' * 30):
        run = len(before) - len(before.rstrip('_'))
        value = 3.1 if run == 36 else (1.7 if run >= 64 else 0.2)
    if token and set(token) == {'·'} and (position == 0 or before.endswith('··')):
        value = 0.26
    if position == 0 and token == '//\n':
        value = 3.37
    if position == 0 and token == 'use':
        value = 1.5
    if tail == '---\ntitle:':
        value = 1.61
    if tail == '#!/usr/bin/env':
        value = -0.99
    if tail == '#!/usr/bin/env python':
        value = 1.05
    return (doc, tail, position + 1), value

"""Approximate the signal for adverbial modifiers after a predicate or object.

Recognize adverbs by dictionary and productive endings, and distinguish a
preceding content word/object from an auxiliary, determiner or clause break.
Weights describe modifier kind and grammatical context. Conservative overall
strength limits false positives; this is local grammar, not a full parser.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# These are grammatical classes, not tokenizer entries.
AUXILIARIES = set('am is are was were be been being have has had do does did '
                  'can could may might must shall should will would'.split())
DETERMINERS = set('a an the this that these those my your his her its our their '
                 'some any no each every another such whose which'.split())
SUBJECTS = set('i we he she they you who someone everyone nobody'.split())
OBJECTS = set('me us him them it myself yourself himself herself itself '
              'ourselves themselves'.split())
PREPOSITIONS = set('to of in on at for from with by into onto upon through '
                   'between about than during before after without within'.split())
CONNECTIVES = set('and or but if when while because although whether then '
                  'however therefore please'.split())
DEGREE = set('more most less least very so too quite rather enough much '
             'little bit lot as'.split())

@lru_cache(maxsize=65536)
def pos(word):
    return wordnet.parts_of_speech(word) if word.isalpha() else frozenset()

@lru_cache(maxsize=65536)
def modifier_strength(word):
    if word in {'again', 'anew', 'once', 'twice', 'thrice'}:
        return 0.97
    if word == 'well':
        return 1.05
    if word in {'better', 'best', 'hard', 'harder', 'fast', 'faster',
                'slow', 'slower', 'deep', 'deeper', 'straight', 'far', 'further'}:
        return 0.44
    if word in {'more', 'less'}:
        return 0.28
    if word in {'most', 'least'}:
        return 0.42
    if word in {'much', 'little', 'enough', 'lot', 'bit'}:
        return 0.39
    if word in {'early', 'earlier', 'late', 'later', 'soon', 'sooner', 'now',
                'today', 'yesterday', 'tomorrow', 'tonight', 'ago', 'forever',
                'overnight', 'afterwards', 'beforehand'}:
        return 0.55
    if word in {'only', 'solely', 'instead', 'altogether', 'too'}:
        return 0.6
    if word in {'first', 'second', 'last', 'next'}:
        return 0.32
    if word == 'often':
        return 0.43
    p = pos(word)
    if word.endswith('ly') and 'adverb' in p:
        return 0.58 if 'adjective' in p else 1.0
    if word.endswith('ly') and not p:
        return 0.24
    if word.endswith(('mente', 'ment')) and not p:
        return 1.22 if word.endswith('mente') else 0.14
    return 0.0


def grammatical_context(previous, before, older):
    if not previous:
        return 0.
    if previous in AUXILIARIES or previous in {'s', 't', 'll', 've', 're'}:
        return -0.06
    if previous in DETERMINERS or previous in SUBJECTS or previous == 'not':
        return 0.03
    if previous in OBJECTS:
        subject_it = previous == 'it' and (not before or before in CONNECTIVES)
        return 0.03 if subject_it else 2.1
    if previous in DEGREE:
        if previous == 'as':
            return 0.55
        # A degree word does not make a preverbal modifier post-verbal.
        if (not before or before in AUXILIARIES or before in DETERMINERS
                or before in PREPOSITIONS or before in SUBJECTS
                or before in CONNECTIVES):
            return 0.48
        return 3.
    if previous in PREPOSITIONS or previous in CONNECTIVES:
        return 0.12
    if previous.isdigit():
        return 0.62
    p = pos(previous)
    nominal_context = before in DETERMINERS or 'adjective' in pos(before)
    if 'verb' in p:
        if previous.endswith(('ed', 'en', 'ing')) or 'noun' not in p:
            return 3.
        if not nominal_context:
            return 2.2
    if 'noun' in p:
        recent = older if before in DETERMINERS else before
        if 'verb' in pos(recent) and recent not in AUXILIARIES:
            return 2.2
        return 0.82
    return 0.83 if 'adverb' in p else 1.


def advance(carry, text, document):
    if carry is None or carry[0] != document:
        previous = before = older = word = ''
    else:
        _, previous, before, older, word = carry
    # Keep just the current word and its three predecessors; punctuation ends clauses.
    for part in re.findall(r'[^\W\d_]+|\d+|[^\w\s]|\s+|_', text):
        if part.isalpha() or part.isdigit():
            word += part.lower()
        else:
            if word:
                older, before, previous, word = before, previous, word, ''
            if any(ch in part for ch in '.!?;,:\n'):
                previous = before = older = ''
    return (document, previous, before, older, word)


def step(carry, prefix, upstream):
    state = advance(carry, prefix.token_strings[-1], prefix.document_ids[-1])
    _, previous, before, older, word = state
    strength = modifier_strength(word)
    role = grammatical_context(previous, before, older)
    if word in {'times', 'time', 'day', 'week', 'month', 'year', 'hour', 'morning'}:
        strength = 0.
        if previous in {'every', 'each', 'per', 'this', 'last', 'next'}:
            strength, role = 0.47, 1.39
        elif word == 'times' and (previous.isdigit() or previous in {
                'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight',
                'nine', 'ten', 'hundred', 'thousand', 'many', 'several',
                'multiple', 'few', 'more'}):
            strength, role = 0.87, (0.62 if previous.isdigit() else 2.4)
    if word in {'much', 'little', 'enough', 'lot', 'bit'} and previous == 'a':
        role = 2.44
    if word == 'well' and previous == 'as':
        strength, role = 0.62, 1.83
    if word == 'only' and previous == 'not':
        role = 1.37
    return state, 0.75 * strength * role

