VOWELS = set('aeiou')
# Stems conventionally completed by n in compressed abbreviations.
ABBREVIATIONS = {
    'eq': -4.2,    # equation
    'sol': -6.0,   # solution
    'ass': -3.8,   # association
    'ex': -3.8,    # exception
    'f': -2.8,     # function / footnote
