        elif last in VOWELS:
            value = 2.1
        elif last == 'm':
            value = 0.0
        elif len(previous.strip()) == 1:
            value = 1.0 if word.startswith('e') else 0.4
        else:
            value = 1.5 if word.startswith('e') else 1.0
            if word.endswith(('a', 'e')):
                value += 0.7
