            value = 2.1 if word.startswith('u') else 0.3
        elif word == 'ct':
            value = 2.4 if last == 'n' else 0.3
        elif word == 'aps' and last == 'i':
            value = 5.0
        elif word == 'inqu':
            value = 2.4
        elif word == 'qu' and last.isalpha() and last != 's':
            value = 0.8
