"""Recognize work words and short r+k spellings, within or across tokens.

Non-a vowels give stronger rk responses than a. Whole common English
words respond less than fragments. Short k-pieces respond most strongly
when joined to a preceding r. Transliteration also covers Cyrillic,
Greek and Arabic. Short endings after rk/lk receive a smaller bump.
A negative offset models document starts; state resets there too.
"""
import re
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
WORK = {
    'work': 1.03, 'works': 1.44, 'worked': 1.62, 'working': 0.74,
    'worker': 1.16, 'workers': 0.61, 'wrought': 1.86,
}
# Spelling of a short piece, its response after r, its ordinary response.
K_PIECES = (
    (r'k', 4.3, 0.0),                 # lone letter
    (r'ke', 5.0, 0.0),
    (r'k[aiouy]', 2.0, 0.0),          # k + vowel
    (r'k[stbldn]', 3.2, 0.25),         # k + consonant
    (r'k(?!h).*', 2.0, 0.0),          # longer piece, not kh
    (r'[ao]ks?', 1.4, -0.3),
    (r'[eiou]ks?', 0.5, 0.0),
)
ALPHABETS = regex.compile(
    r'[\p{Latin}\p{Cyrillic}\p{Greek}\p{Arabic}]'
)
ENDINGS = {'ed', 'ing', 'er', 'ers', 's', 'is', 'en', 'ung'}


@lru_cache(maxsize=65536)
def spelling(token):
    return anyascii(token).lower() if ALPHABETS.search(token) else ''


def predict(token, previous, first):
    s, p = spelling(token), spelling(previous)
    core = s.strip(' \t\r\n._-/')
    joined = s[:1].isalpha()
    value = -0.36 if first else 0.0
    if core in WORK:
        value += WORK[core]
        if joined and p[-1:].isalpha():
            if core in {'work', 'works', 'worker'}:
                value += 1.3
            elif core == 'working':
                value += 0.3
    elif len(core) <= 6 and 'rk' in s:
        if 'ark' in s:
            value += 0.4 if joined else 0.1
        elif joined:
            value += 2.8
        else:
            frequency = zipf_frequency(core, 'en')
            value += 1.9 - 1.3 * max(0.0, frequency - 4.0)
        if joined and p.endswith('w'):
            value += 4.0
    if joined and re.search(r'r[aeiou]k', s):
        value += 0.4
    if joined and len(s) <= 6:
        for pattern, after_r, ordinary in K_PIECES:
            if re.fullmatch(pattern, s):
                value += after_r if p.endswith('r') else ordinary
                if p.endswith('wer'):
                    value += 2.4
                elif p.endswith('l'):
                    value += 0.3
                break
    if joined and s in ENDINGS and re.search(r'[rl]k$', p):
        value += 1.1
    return float(value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    return (document, token), predict(token, previous, first)

