"""Pipe-like separators and 'a few'.

Fires on vertical-bar tokens (" |", "|", "||", "|\n", "│"), strongest on the
spaced pipe " |" that separates fields in lists and tables, weaker on the
first pipe in a document than on later ones. Also fires on "few" after "a".
Every other token predicts 0, except the first token of a document, which is
slightly negative.
"""
READS = ()

def is_pipe(tok):
    return ("|" in tok or "│" in tok) and not tok.startswith("<|")

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    doc = prefix.document_ids
    if carry is None or len(doc) == 1 or doc[-1] != doc[-2]:
        pipes = 0
        new_doc = True
    else:
        pipes = carry
        new_doc = False
    if new_doc:
        value = -0.2
    elif tok == " |":
        value = 2.1 if pipes == 0 else max(1.5, 2.1 - 0.05 * pipes)
    elif is_pipe(tok):
        value = 1.0
    elif tok == " few":
        value = 1.6 if prev == " a" else 0.8
    else:
        value = 0.0
    if is_pipe(tok):
        pipes += 1
    return pipes, float(value)

