"""Approximate explanatory asides and consequence clauses.

Negative pulses mark prose parentheses/citations, 'which' clauses, and
comma-attached participles, especially 'making' and 'leading'. A pulse may
continue onto the next linking word or citation digit. Most tokens stay near
zero. This uses spelling and grammar, not a table of token IDs.
"""
import re

READS = ()
RESULT = set('''
causing forcing prompting resulting allowing enabling ensuring indicating
implying suggesting meaning demonstrating showing revealing leaving rendering
giving providing adding creating forming bringing contributing reducing
increasing improving enhancing preventing confirming reflecting
'''.split())
INFERENCE_OR_CAUSATION = set('''
suggesting indicating confirming forcing prompting leaving rendering
'''.split())
FUNCTION = set('''
if else for while switch return and or not is are was were be a an the
in on at of by as to from with
'''.split())
RESULT_VERBS = set('''
mean means make makes give gives lead leads cause causes allow allows
suggest suggests indicate indicates result results show shows
'''.split())
COMMA_WORDS = {'which': -0.60, 'with': -1.57, 'a': -0.15, 'an': -0.15,
               'the': 0.08, 'that': 0.40, 'then': 0.25}
ENDINGS = {('leading', 'to'): -1.51, ('resulting', 'in'): -2.23,
           ('due', 'to'): -0.38, ('opposed', 'to'): -0.38,
           ('rather', 'than'): -0.53}
REFERENCE = r'(?:[A-Za-z][.)]? +\[|\.\[)\d*(?:[,\-– ]\d*)*$'


def predict(t, p, q, tail, citing):
    w, prev = t.strip(), p.strip()
    comma = p.rstrip().endswith((',', '，'))
    start = not p or p == '<|endoftext|>'
    value = -0.001
    word = w.lower()
    if not t.startswith(' ') and p[-1:].isalpha():
        match = re.search(r'[A-Za-z]+$', tail)
        word = (match.group() if match else '').lower() + word
        comma |= p.isalpha() and q.rstrip().endswith(',')

    # Distinguish explanatory prose brackets from mathematical/code syntax.
    if t in {' (', ' [', '.['}:
        paren = t == ' ('
        value -= 0.18 if paren else 0.06
        if prev[-1:].isalpha():
            value -= 0.25 + (0.10 if prev.islower() else 0)
        if prev[-1:].isdigit():
            value -= 0.31
        if citing:
            value -= 0.20 if paren else 0.67
        if paren and prev.lower() in FUNCTION:
            value += 0.44
    if w == '(' and not t.startswith(' '):
        value -= 0.04
    if w == '（':
        value -= 0.30
    if w.startswith(('[@', '([')) or w == '][':
        value -= 0.50

    if w.lower() == 'which':
        value -= 0.37
        if prev.lower() == 'after':
