        value += COMMA_WORDS.get(w, 0)
    if w.lower() in {'while', 'whereas', 'although', 'though'}:
        value -= 0.16 + (0.65 if comma else 0)

    # A morphological heuristic for participles, with common non-verb endings.
    gerund = word.endswith('ing') and len(word) > 4 and word not in {
        'thing', 'something', 'anything', 'nothing', 'everything', 'during',
        'morning', 'evening', 'spring', 'string', 'king', 'ceiling'}
