        value += 0.04
        if comma and not w[:1].isupper() and word not in {
                'including', 'using', 'according'}:
            value -= 0.63
            if word in RESULT:
                value -= 1.35
            if word in INFERENCE_OR_CAUSATION:
                value -= 1.19
            if word == 'making':
                value -= 3.21
            if word == 'leading':
                value -= 2.68
    if prev.lower() == 'which':
        if w in {'is', 'was', 'has', 'can', 'could', 'may', 'might', 'will'}:
            value -= 0.51
    if prev.lower() in {'which', 'this', 'that'} and w in RESULT_VERBS:
        value -= 0.29 + (0.36 if prev.lower() == 'which' else 0)
        if w in {'mean', 'means'}:
            value -= 0.88
        if w in {'make', 'makes'}:
            value -= 0.27 + (0.66 if prev.lower() == 'which' else 0)
    value += ENDINGS.get((prev, w), 0)
    if w in {'This', 'These', 'Those'} and not start:
        value -= 0.30 if w == 'This' else 0
        if p.rstrip().endswith(('.', '!', '?')):
            value -= 0.25
        if '\n' in p:
