        value -= 0.45 + (0.31 if citing else 0)
    if w == 'respectively':
        value -= 0.56
    if start:
        value += 0.17 if w.isalpha() else 0
        value += 0.07 if w[:1].isupper() else 0
    return value


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', False)
    _, p, q, tail, citing = carry
    t = prefix.token_strings[-1]
    value = predict(t, p, q, tail, citing)
    text = tail + t
