"""Clause-comment openers: layers.1.mlp.down_proj:353.

The component goes strongly negative on the first word of a phrase that comments on the
clause just before it, the place where a writer adds "...and this means / results in ...":

- an -ing participle after a comma that states a result or comment (", making it easier",
  ", leading to", ", indicating that", ", suggesting"): about -2.5;
- any other -ing participle after a comma (", taking", ", using"; not the prepositions
  ", including", ", during", ", according"): about -0.6;
- ", which" and ", with" (absolute phrase), ", while", ", whereas", ", thus": -1.0 to -1.7;
- a citation or parenthetical opener: " (" after a word (-0.4; after a function word such
  as "and" or "for", nothing) and " [" (-0.3); the digit right after "[" (-0.3);
- other "which", "means", "makes", "suggests", "Figure" (-0.3 to -0.4);
- a sentence-initial "This" (-0.6), and the verb right after ", which" or " which" ("which is", -0.6).

Small positives: ", that" and ", then" (+0.3 to +0.4), and the first token of a document (+0.16).
Everything else is 0. This is a hand-written rule set; the numbers are rough averages.
"""

READS = ()

COMMA = {",", "，"}
FUNCTION_WORDS = {" and", " or", " for", " by", " of", " in", " to", " the", " a", " an", " with",
                  " from", " on", " at", " as", " is", " was", " that", " than", " are", " be",
                  " using", " via", " per", " under", " among", " over", " into", " between",
                  " within", " about", " which"}
RESULT_VERBS = {" making", " leading", " leaving", " giving", " resulting", " creating",
                " allowing", " meaning", " causing", " providing", " adding", " indicating",
                " suggesting", " confirming", " prompting", " ensuring", " preventing",
                " showing", " enabling", " rendering", " demonstrating", " revealing"}
PREPOSITIONS = {" including", " during", " according", " depending", " following",
                " regarding", " concerning", " considering"}
AFTER_COMMA = {" which": -1.0, " with": -1.7, " while": -1.0, " whereas": -1.0, " thus": -0.7,
               " that": 0.4, " then": 0.3}
ANYWHERE = {" which": -0.4, " while": -0.3, " [": -0.3, " means": -0.3, " meaning": -0.3,
            " makes": -0.4, " suggests": -0.4, " Figure": -0.3}


def is_participle(word):
    core = word.strip()
    return word.startswith(" ") and core.isalpha() and core.endswith("ing") and len(core) > 4


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    before = "" if new_doc else prefix.token_strings[-2]
    if new_doc:
        value = 0.16
    elif before in COMMA and word in RESULT_VERBS:
        value = -2.5
    elif before in COMMA and is_participle(word) and word not in PREPOSITIONS:
        value = -0.6
    elif before in COMMA and word in AFTER_COMMA:
        value = AFTER_COMMA[word]
    elif word in ANYWHERE:
        value = ANYWHERE[word]
    elif word == " (" and before not in FUNCTION_WORDS:
        value = -0.4
    elif word == " This" and before == ".":
        value = -0.6
    elif before in (" which", ",which") and word == " is":
        value = -0.6
    elif before in (" [", "[") and word.strip().isdigit():
        value = -0.3
    else:
        value = 0.0
    return carry, float(value)

