"""Mostly a comma-after-discourse-cue signal, not a list-comma signal.

Recognize connecting words, interjections and introductory phrases in a short
text tail. Weaken closing commas around parenthetical connectives. Also model
the separate negative response to a document-initial 'Title:' field. Smaller,
idiosyncratic activations on ordinary tokens are left at zero; an initial
numeric token gets a small negative estimate.
"""
import re

READS = ()

COORDINATORS = set('and or but if because since although unless plus'.split())
RELATIVES = set('who which that where when while though'.split())
INTERJECTIONS = set('yes no yeah well okay ok hey hi hmm hmmm oh oops sure '
                    'yep alas ah wow alright uh er'.split())
# These are discourse cues rather than arbitrary tokenizer entries.
CUE_GROUPS = (
    (1.30, 'therefore thus hence now then'),
    (1.10, 'wait'),
    (0.98, 'however alternatively also still otherwise consequently '
           'nevertheless nonetheless indeed'),
    (0.80, 'moreover furthermore additionally instead rather anyway '
           'similarly likewise finally first second third firstly secondly '
           'next overall meanwhile specifically besides maybe perhaps'),
    (1.00, 'actually again accordingly'),
)
CUES = {word: value for value, words in CUE_GROUPS for word in words.split()}
PHRASES = (
    'for example', 'for instance', 'in fact', 'that is', 'in other words',
    'in particular', 'in addition', 'in general', 'in this case',
    'in that case', 'in any case', 'at the same time', 'in turn',
    'as a result', 'on the other hand', 'by the way', 'in contrast',
    'by contrast', 'in effect', 'in reality', 'in this sense',
    'in that sense', 'at any rate', 'in the meantime', 'as such',
    'let me see', "let's see", 'that is to say', 'most importantly',
)
FOREIGN_CUES = (
    'однако', 'таким образом', 'кроме того', 'что', 'например',
    'pero', 'mais', 'porém', 'que', 'che', 'qui', 'cependant',
    'enfin', 'en effet', 'en particulier', 'en este caso',
    'tuttavia', 'sin embargo', 'no entanto',
)
CHINESE_CUES = (
    '所以', '因此', '于是', '然而', '但是', '不过', '同时', '此外',
    '另外', '对此', '为此', '首先', '其次', '最后', '总之',
    '例如', '比如', '当然', '其实', '那么', '或许', '总的来说',
)


def ends_phrase(text, phrase):
    return text.endswith(phrase) and (
        len(text) == len(phrase) or not text[-len(phrase)-1].isalpha())


def comma_value(text):
    text = text.rstrip().rstrip('.')
    lower = text.lower()
    if text.endswith(CHINESE_CUES):
        return 0.90
    if any(ends_phrase(lower, p) for p in FOREIGN_CUES):
        return 1.00
    for phrase, value in (('of course', 1.15), ('i mean', 1.25),
                          ('this way', 1.00), ('that way', 1.00),
                          ('e.g', 0.40), ('i.e', 0.65)):
        if ends_phrase(lower, phrase):
            before = lower[:-len(phrase)].rstrip()
            return 0.20 if before.endswith(',') else value
    for phrase in PHRASES:
        if ends_phrase(lower, phrase):
            before = lower[:-len(phrase)].rstrip()
            if before.endswith(','):
                return 0.30
            return 0.85
    match = re.search(r'(\w+)$', text)
    if not match:
        return 0.02
    word = match[1]
    low, capital = word.lower(), word[0].isupper()
    before = lower[:match.start()].rstrip()
    if low == 'so':
        return 1.65 if capital else 0.65
    if low in COORDINATORS:
        return 1.30 + (0.20 if capital else 0.0)
    if low in RELATIVES:
        return 1.20 if low in {'who', 'which'} else 0.65
    if low in CUES:
        value = CUES[low] - (0.22 if not capital else 0.0)
        if low in {'however', 'therefore', 'indeed', 'nevertheless'}:
            if before.endswith(','):
                return 0.70 if re.search(r'\b(and|or|but),$', before) else 0.22
        if low in {'now', 'then', 'again', 'first', 'second'} and not capital:
            return 1.00 if re.search(r'\b(so|but|and|wait)\s*$', before) else 0.20
        return value
    if low in INTERJECTIONS:
        return 0.75 if capital else 0.40
    if low in {'here', 'there', 'today', 'recently', 'already', 'see', 'why'}:
        return 0.90 if capital else 0.25
    if low in {'is', 'are', 'was', 'were', 'would', 'should', 'could',
               'must', 'can', 'may', 'will', 'has', 'have', 'had'}:
        return 0.45
    if low in {'of', 'to', 'as', 'by', 'with', 'from', 'at', 'in', 'on',
               'for', 'this', 'these', 'those', 'i', 'you', 'we', 'they', 'me'}:
        return 0.25
    if low.endswith('ly') and len(low) > 4:
        return 0.60 if capital else 0.20
    return 0.0 if low.isdigit() else 0.02


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = 0.0
    comma = re.search('[,，]', token)
    if token == ':' and tail == 'Title':
        value = -2.59
    elif comma:
        value = comma_value(tail + token[:comma.start()])
        if '\n' in token:
            value *= 0.60
        if any(c in token for c in '"”’') or any(c.isalpha() for c in token):
            value *= 0.35
    elif token == '、':
        value = 0.15
    elif not tail and token.strip().isdigit():
        value = -0.15
    return (document, (tail + token)[-100:]), value

"""Recognize written negation, with language-dependent strength.

Most tokens contribute zero.  English 'not' and contracted n't usually have a small
negative response; several other languages' negative particles have much larger
ones.  For ambiguous spellings (Spanish 'no', Italian 'non', Polish 'nie',
Hungarian 'nem', Romanian 'nu'), use word frequencies in the preceding text to
recognize the surrounding language, rather than treating every occurrence as
negation in that language. English strength also depends on the preceding
auxiliary: forms of 'be' are stronger than 'do', and can't/couldn't are weak.
Uncontracted 'can not' is an exception with a positive value; word-initial
English 'no' also gets a small positive value. No future word is inspected.
"""
import regex as re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=50000)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_of(text, languages):
    words = re.findall(r"\p{Latin}{2,}", text.lower())
    words = [w for w in words if w not in {'no', 'non', 'nie', 'nem', 'nu'}][-20:]
    if not words:
        return 'en'
    return max(languages, key=lambda lang: sum(
        0.9 ** age * frequency(word, lang)
        for age, word in enumerate(reversed(words))))


# Less ambiguous negative particles, not an exhaustive list of negative words.
NEGATION = {
    'não': -9.3, 'nao': -7.7,
    'не': -3.4, 'nicht': -1.6, 'niet': -2.5,
    'inte': -2.55, 'ikke': -1.9, 'tidak': -4.3,
    'pas': -0.47, 'ne': -0.7, 'không': -0.55,
    'لا': -1.6, 'ولا': -1.2,
    'sin': -0.05, 'sem': -0.25, 'ni': -0.3,
    'nunca': -1.1, 'sino': -2.1, 'sinon': -3.6,
    '不': -0.64, '不是': -0.45, 'δεν': -4.8,
}


SPLIT_ENDINGS = {w[i:] for w in ('não', 'nie', 'nicht', 'tidak', 'δεν')
                 for i in range(1, len(w))}

def english_negation(previous, token):
    match = re.search(r"[a-zA-Z']+$", previous.replace('’', "'"))
    auxiliary = match.group().lower() if match else ''
    if token.lower() in ("'t", '’t'):
        if auxiliary in {'isn', 'wasn', 'weren', 'aren', 'ain'}:
            return -0.86
        if auxiliary in {'can', 'couldn', 'haven'}:
            return -0.28
        if auxiliary == 'doesn':
            return -0.67
        if auxiliary == 'shouldn':
            return -0.44
        return -0.56
    if token.strip() == 'NOT':
        return -0.45
    if auxiliary in {'am', 'is', 'are', 'was', 'were'} or auxiliary.endswith(
            ("'s", "'m", "'re")):
        return -1.07
    if auxiliary in {'do', 'did'}:
        return -0.68
    if auxiliary == 'does':
        return -0.78
    if auxiliary == 'can':
        return 0.78
    if auxiliary in {'could', 'may', 'if'}:
        return -0.60
    if auxiliary == 'need':
        return -0.33
    return -0.85 if token == ' not' else -0.64


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().strip('_/\\-"\'`([{<>:').lower()
