        value = english_negation(previous, token)
    elif word == 'no':
        lang = language_of(previous, 
            ('en', 'es', 'pt', 'fr', 'it', 'cs', 'ro', 'de', 'pl'))
        if previous.endswith(('¿', '¡')):
            lang = 'es'
        value = -11.5 if lang == 'es' else 0.3
    elif word == 'non':
        lang = language_of(previous, ('en', 'it', 'fr'))
        value = -11.0 if lang == 'it' else -6.2 if lang == 'fr' else -0.7
    elif word == 'nie':
        lang = language_of(previous, ('en', 'pl', 'de', 'nl', 'es'))
        value = -6.1 if lang == 'pl' else -0.2
    elif word == 'nem':
        lang = language_of(previous, ('en', 'hu', 'pt', 'it', 'cs'))
        value = -9.2 if lang == 'hu' else -2.4 if lang == 'pt' else -0.6
    elif word == 'nu':
        lang = language_of(previous, ('en', 'ro', 'sv', 'nl', 'it', 'fr'))
        value = -10.0 if lang == 'ro' else -1.1
