            value = -10.5
        elif complete == 'nie':
            value = -6.5
        elif complete == 'nicht':
            value = -2.0
        elif complete == 'tidak':
            value = -6.3
        elif complete == 'δεν':
            value = -4.8
    return (doc, (previous + token)[-384:]), value

"""A negative pulse for recent year numbers and calendar-date separators.

Read the trailing four digits as a possible year, even inside an identifier.
The learned year response is strongest around 2020--2023 and fades after 2024.
A nearby English month slightly strengthens recent-year responses. Hyphens,
slashes, and East Asian year markers also respond after a year number.
A separate rule approximates responses at Java/Android/Spring package imports.
These recurring training patterns are retained; other text is left at zero.
"""
import re

READS = ()

# Amplitudes for the consecutive calendar years 2015 through 2026.
YEAR_RESPONSE = (
    -0.27, -0.61, -1.38, -1.87, -3.50, -4.55,
    -5.25, -6.05, -5.75, -4.85, -0.8, -0.3,
)
MONTH = re.compile(
    r'\b(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|'
    r'Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|'
    r'Nov(?:ember)?|Dec(?:ember)?)\b', re.I
)
YEAR_END = re.compile(r'((?:19|20)[0-9]{2})\Z')


def package_response(before, token):
    """A smaller, separate response to Java import/package syntax."""
    if re.search(r'\b(?:import|package)$', before):
        if token == ' org':
            return -1.4
        if token == ' static':
            return -2.4
    if re.search(r'\bimport (?:java|android)$', before):
        if token == '.util':
            return -1.9
        if token in ('.text', '.time'):
            return -3.0
    if re.search(r'\bimport android$', before):
        # Android framework package categories.
        return {'.content': 4.5, '.app': 2.5, '.view': 2.1,
                '.widget': 1.2}.get(token, 0.0)
    if re.search(r'\bimport org\.springframework(?:\.\w+)*$', before):
        # Spring framework: containers, configuration and data models.
        return {'.core': 5.6, '.context': 4.0, '.domain': 3.7,
                '.stereotype': 3.6}.get(token, 0.0)
    return 0.0


