    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else b''
    token = prefix.token_strings[-1]
    before = history.decode('utf-8', 'ignore')
    history = (history + prefix.token_bytes[-1])[-180:]
    text = history.decode('utf-8', 'ignore')
    value = 0.0

    if token.isascii() and token.isdigit():
        match = YEAR_END.search(text)
        if match:
            year = int(match[1])
            if 2015 <= year <= 2026:
                value = YEAR_RESPONSE[year - 2015]
                if len(text) > 4 and text[-5].isdigit():
                    value *= 0.6
                if 2020 <= year <= 2024 and MONTH.search(before[-40:]):
                    value -= 0.6
    else:
        match = YEAR_END.search(before)
        if match:
            year = int(match[1])
            if token == '-':
                value = -max(0.2, min(5.5, (year - 1995) * 0.2))
            elif token == '/':
                value = -max(0.1, min(2.2, (year - 1998) * 0.09))
            elif token == '–':
                value = -0.6 if year >= 2000 else -0.3
        marker = re.search(r'((?:19|20)[0-9]{2})\s?年(?:度)?\Z', text)
        if marker and not before.endswith(('年', '年度')):
            year = int(marker[1])
            value = -max(0.15, min(4.2, (year - 2000) * 0.17))
            if token == "\ufffd":
                value *= 1.4

    if value == 0.0:
        value = package_response(before, token)
    return (doc, history), value

