"""Recent-year detector: a negative response on years 2016-2024 (the last digit of "20XY") and on
the date separator right after a year 20XX (strongest for recent years)."""
READS = ()

# Mean activation on the last digit of "20XY", by year (2016-2026; earlier years about 0).
YEAR_DIGIT = {2016: -0.6, 2017: -1.4, 2018: -1.9, 2019: -3.3, 2020: -4.6, 2021: -5.5,
              2022: -6.2, 2023: -6.2, 2024: -4.2, 2025: -0.4, 2026: -0.3}
# Mean activation on a separator after a year, by the year's decade digit (2000s, 2010s, 2020s).
SEPARATOR = {"-": {"0": -2.0, "1": -3.7, "2": -5.5},
             "年": {"0": -1.0, "1": -2.4, "2": -4.1},
             "/": {"0": -0.6, "1": -1.6, "2": -1.9}}
DIGITS = set("0123456789")


def step(carry, prefix, upstream):
    s = prefix.token_strings
    d = prefix.document_ids
    t = prefix.position
    if t < 3 or d[t] != d[t - 3]:
        return None, 0.0
    if s[t] in DIGITS and s[t - 3] == "2" and s[t - 2] == "0" and s[t - 1] in DIGITS:
        return None, YEAR_DIGIT.get(int("20" + s[t - 1] + s[t]), 0.0)
    if t >= 4 and d[t - 4] == d[t] and s[t - 4] == "2" and s[t - 3] == "0" and s[t - 2] in DIGITS \
            and s[t - 1] in DIGITS and s[t] in SEPARATOR:
        return None, SEPARATOR[s[t]].get(s[t - 2], 0.0)
    return None, 0.0

programs.sol:
"""Approximate this component with formatting and character-shape rules.

Document-opening Markdown markers are strongly positive; opening chat markers
and assignment signs are negative. The blank line after a closing reasoning
tag is mildly negative. Capitals W--Z are suppressed inside long, mixed-case
alphanumeric runs resembling Base64. Repeated middle-dot filler is positive.
Most lexical variation is deliberately left at a near-zero background.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, run = ('', '') if first else carry[1:]

    # Keep a short tail of a continuous encoding-alphabet run, across line wraps.
    if token and token.isascii() and all(
        c.isalnum() or c in '+/=' for c in token
    ):
        run = (run + token)[-80:]
    elif token not in ('\n', '\r', '\r\n'):
        run = ''
    encoded = (len(run) >= 16 and any(c.isupper() for c in run)
               and any(c.islower() for c in run)
               and any(c.isdigit() for c in run))

    value = -0.002
    if first:
        if token in ('#', '##', '###'):
            value = (2.584, 3.042, 2.253)[len(token) - 1]
        elif token in ('**', '__'):
            value = 1.50
        elif token.startswith(('"""', "'''")):
            value = 2.0
        elif token == '```':
            value = 1.20
        elif token.startswith(' ') and token.strip() in ('=', ':='):
            value = -1.0
        elif token == '<|im_start|>':
            value = -0.258
        elif token == '<|endoftext|>':
            value = 2.503
        elif token == '\t':
            value = -0.614
        elif token.isspace():
            value = 0.355
    elif token == '\n\n':
        value = -0.15 if previous == '</think>' else -0.014
        if previous == '<think>':
            value = -0.05
    elif token.isascii() and token.isalpha() and token.isupper():
        terminal_capitals = len(set(token) & set('WXYZ'))
        if encoded:
            value = -0.11 - 1.05 * terminal_capitals
        elif terminal_capitals:
            value = 0.06
    if token == '··' and (first or previous == token):
        value = 1.40
    return (doc, token, run), value

programs.haiku:
"""Prepositions, mostly outside English, are negative; English ones only when they open a phrase.

What the component does: it writes a strong negative signal at prepositions that begin a
prepositional phrase. German, Russian, Persian, Spanish/Portuguese and Chinese prepositions
(durch, bei, mit, в, en, 通过 ...) are negative almost wherever they occur. English prepositions
are negative mainly when they open a clause or phrase: right after 'and', 'but', 'which', 'that',
after a comma, or at a sentence start ('..., in the', 'and in', 'which in turn', '. In 2003').
English 'in' is the strongest of them. Commas are also negative when they follow a clause-opening
word such as 'and,', 'which,', 'who,', 'if,'. Everything else is about zero.
"""
READS = ()

# Prepositions that are negative wherever they appear (German, Persian: strongest).
STRONG_PREP = set("durch bei nach mit unter ohne vor auf über aus gegen در به با".split())
# Prepositions of other languages: negative, weaker mid-sentence.
FOREIGN_PREP = set("""für zu im vom zur zum bis von en por con para pour par em per na
в на с по при для за от из у во через
通过 从 对 向 为 以 由 凭借 除了 按照 根据 关于 对于 经 同 比 照 使用 利用 因 在""".split())
# English prepositions: fire only when opening a phrase.
EN_PREP = set("in at on by for from with during after under through while without within per".split())
# Words after which a phrase or clause is opening.
LINKERS = {"and", "but", "or", "nor", "so", "that", "which", "who", "whom", "where", "when", "because",
           "if", "as", "while", "except", "only", "also", "und", "y", "et"}
# Commas after these clause-openers are strongly negative; after these weakly.
COMMA_STRONG = {"and", "who", "which", "whom", "when", "if", "where", "because", "que", "che", "since"}
COMMA_WEAK = {"that", "but", "or", "et", "nor", "mais", "или"}
PUNCT = {";", ":", "(", ".", "!", "?", ")", "—", "-"}


def opening(prefix):
    """Where the token sits: 'start' (document or line start), 'linker', 'comma', 'punct' or 'other'."""
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return "start"
    before = prefix.token_strings[-2]
    if before.endswith("\n"):
        return "start"
    if before.strip().lower() in LINKERS:
        return "linker"
    if before.strip() == ",":
        return "comma"
    if before.strip() in PUNCT:
        return "punct"
    return "other"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.strip().lower()
    where = opening(prefix)
    opens = where != "other"

    if token == ",":
        before = prefix.token_strings[-2].strip().lower() if len(prefix.token_ids) > 1 else ""
        if before in COMMA_STRONG:
            return carry, -1.5
        if before in COMMA_WEAK:
            return carry, -0.5
        return carry, 0.0

    # Only whole words count: spaced or capitalised, or non-Latin script (not a word fragment).
    whole = token.startswith(" ") or token[:1].isupper() or not token[:1].isascii()
    if not whole:
        return carry, 0.0
    if lower in STRONG_PREP:
        return carry, (-1.9 if opens else -1.4)
    if lower in FOREIGN_PREP:
        return carry, (-0.9 if opens else -0.4)
    if lower in EN_PREP:
        if lower == "in":
            return carry, {"linker": -1.2, "comma": -0.9, "punct": -0.7, "start": -0.6, "other": -0.1}[where]
        return carry, {"linker": -0.5, "comma": -0.2, "punct": -0.2, "start": -0.2, "other": 0.0}[where]
    return carry, 0.0

programs.sol:
"""A pulse on opening quotes of dictionary/JSON keys.

A comma after a short string-valued field is the strongest cue. Quotes after
colons are values instead. Braces and scalar-valued fields also introduce
keys. The detector uses recent punctuation, not the identities of field names.
Escaped code is recognized too, but escaped line breaks weaken the pulse.
There are also small positive pulses on adjacent decimal digits: 1 after
1--3, or 0 after 3. The second digit of document-initial "12" is much larger.
"""
import re
READS = ()


def unescape(text):
    text = re.sub(r'\\+(["\'])', r'\1', text)
    return re.sub(r'\\+n', '\n', text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = unescape(token)
    value = 0.0
    if text.endswith(('"', "'")) and not any(c.isalnum() for c in text):
        quote = text[-1]
        # Preserve the distinction between actual and serialized newlines.
        raw = tail + text[:-1]
        serialized_line = bool(re.search(r'\\+n\s*$', raw))
        before = unescape(tail + text[:-1]).rstrip()
        if before.endswith(':'):
            value = 0.06
        elif before.endswith('{'):
            if '{' in text:
                value = -0.15 if text.startswith(' ') else 0.04
            else:
                value = -1.2 if quote == '"' else -0.85
        elif before.endswith(','):
            previous = before[:-1].rstrip()
            if previous.endswith(('"', "'")):
                q = previous[-1]
                start = previous.rfind(q, 0, len(previous)-1)
                if start >= 0:
                    content = previous[start+1:-1]
                    context = previous[:start].rstrip()
                    if context.endswith((':', '=>')):
                        strength = 1.0 if context.endswith('=>') else 1.85
                        value = -strength / (1 + len(content)/180)
                    elif context.endswith('['):
                        value = -0.05
                    elif context.endswith('('):
                        function = context[:-1].rstrip()[-1:]
                        value = 0.08 if function.isalnum() else -0.4
                    elif quote == "'":
                        value = -0.25
                    elif context.rfind('[') > context.rfind('{'):
                        value = -0.15
            elif previous.endswith(('}', ']')):
                value = -0.8
            # Scalar or expression-valued field: look for its quoted key.
            elif re.search(r'''["'][^"'\n]+["']\s*(?::|=>)[^,\n]*$''', previous):
                value = -1.3
        if serialized_line and value < 0:
            value *= 0.5
    if token == '1' and tail[-1:] in ('1', '2', '3'):
        value = 0.2
    elif token == '0' and tail.endswith('3'):
        value = 0.32
    if tail == '1' and token == '2':
        value = 4.97
    return (doc, (tail + token)[-2000:]), value

programs.haiku:
"""Opening quote of a dictionary or JSON key, after a comma.

The component goes strongly negative on the quote mark that opens a key in a
key/value object, such as {"name": "bash", "arguments": {...}} or
{'a': 1, 'b': 2}. The quote opening the second key is about -1.7; each later key
makes it about 20% weaker. A quote opening an item after a comma inside a list
or bracketed array is weakly negative (-0.5), and a quote that starts a new line
inside braces or brackets is about -0.7. Quotes in prose, in function arguments
and all other tokens are about 0.

Bracket depth is tracked through the row (reset at each new document), so the
rule knows whether the quote sits inside an object. Rows can start mid-object;
then a recent "key": or 'key': token stands in for the open brace.
"""

READS = ()
KEY_ENDS = ("':", '":')


def is_quote(token):
    text = token.lstrip(" ")
    return text[:1] in ('"', "'") or text.startswith('\\"')


def step(carry, prefix, upstream):
    # carry: the open brackets, innermost last, as [bracket, commas seen inside it]
    stack = [] if carry is None else [list(each) for each in carry]
    docs = prefix.document_ids
    if len(docs) > 1 and docs[-1] != docs[-2]:
        stack = []
    tokens = prefix.token_strings
    token = tokens[-1]
    previous = tokens[-2] if len(tokens) > 1 else ""
    value = 0.0
    if is_quote(token):
        if stack:
            kind, commas = stack[-1]
        elif any(each.endswith(KEY_ENDS) for each in tokens[-14:-1]):
            kind, commas = "{", 1
        else:
            kind, commas = "", 0
        after_comma = previous.endswith(",") or ("," in token and token[-1] in "\"'")
        after_space = previous.strip() == ""
        if kind == "{" and after_comma:
            value = -1.7 * 0.8 ** (max(commas, 1) - 1)
        elif kind == "[" and after_comma:
            value = -0.5
        elif kind in ("{", "[") and after_space:
            value = -0.7
    for char in token:
        if char in "{[(":
            stack.append([char, 0])
        elif char in "}])" and stack:
            stack.pop()
    if stack and "," in token:
        stack[-1][1] += 1
    return stack, value

programs.sol:
"""A boundary/spacing predictor, not a word-identity lookup.

Document openings have a large transient: space-prefixed words are usually
negative, while digits, short fragments, and punctuation are positive.  Runs
of an opening separator retain that response.  Later, the main positive
responses are whitespace tokens continuing indentation, especially the last
single space, and tabs following printed line numbers.  Ordinary text is near
zero.  These are coarse training-set averages; lexical exceptions are omitted.
"""
import math
import keyword

READS = ()
CODE_WORDS = set(keyword.kwlist) | set(
    'function var let const public private protected package namespace using '
    'include typedef void int string boolean char return import export class def'
    .split()
)
QUESTIONS = set('how what why when where who which whose whom'.split())


def opening(s):
    w = s.strip()
    if s.isspace():
        if s == '\r':
            return 35.0
        if '\t' in s:
            return 13.0 - math.log1p(len(s))
        if '\xa0' in s:
            return 13.0
        return 5.0 - 0.3 * math.log1p(len(s))
    if w.isdecimal():
        return 5.1
    if w.isalpha():
        if s.startswith(' '):
            if len(w) == 1:
                return 0.2
            return -2.5 if w.islower() else -1.2
        if w.lower() in QUESTIONS:
            return -5.0
        if len(w) == 1:
            return 5.2 if w.isascii() else 2.4
        if w in CODE_WORDS:
            return 4.0
        if w.isupper() and w.isascii():
            return 3.5
        return 1.7 if len(w) < 4 else 1.2
    if s in ('\\n', '\\t'):
        return 15.0
    if not any(c.isalnum() for c in w):
        if len(w) > 1 and set(w) <= set('·^'):
            return 22.0  # dot leaders and caret underlines
        if '*' in w:
            return 12.0
        if w == '//' and '\n' in s:
            return 40.0
        return 3.0 + min(len(w), 5) * 0.65 + float('\n' in s)
    return 1.5


def spacing(s, previous):
    if '\n' in s or '\r' in s:
        return 0.0
    if not s.isspace():
        return 0.0
    after_line = previous.endswith(('\n', '\\n'))
    after_white = previous.isspace() and not after_line
    if set(s) == {' '}:
        if len(s) == 1:
            if after_white:
                n = len(previous)
                return 0.65 if n == 1 else 2.8 if n <= 4 else 1.9
            return 0.32 if after_line else 0.0
        if after_line:
            return 0.0
        if after_white:
            return 0.4
        # Four-column indentation, with the next word supplying a space.
        return 1.05 if len(s) % 4 == 3 else 0.13
    if '\xa0' in s:
        if len(s) > 1:
            return 0.7
        if previous.isspace() and len(previous) > 2:
            return 3.8
        return 1.95 if '`' in previous else 0.06
    if '\t' in s:
        if previous.isdecimal():
            return 1.55
        if after_line:
            return -0.1
        return 1.0 if after_white else 0.5
    return 0.5


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        first, only_repetitions, previous = s, True, ''
    else:
        _, first, only_repetitions, previous = carry
        only_repetitions = only_repetitions and s == first
    value = opening(s) if only_repetitions else spacing(s, previous)
    return (document, first, only_repetitions, s), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:361 -- fires on whitespace, and on the first token of a document.

Two things drive this component's contribution, both read straight off the tokens:

1. Document start (the first token after a document boundary, where the model sees
   nothing before it). Its value depends only on the token itself:
   - a token starting with a space and then a word, e.g. " the", " how", " using"
     (a sentence picked up mid-way) pushes it negative, about -2;
   - a digit, a symbol or punctuation, or a whitespace/control token (e.g. "1", "#",
     "\t", "/*") pushes it positive, about +4;
   - any other token (a bare word, "The", "How", a fragment) is mildly positive, about +2.

2. Indentation runs inside a line. Code indentation is often split into several
   whitespace tokens. The second and later pieces of such a run fire:
   - a single space after a run of two or more spaces or tabs fires strongly, about +2.8;
   - a single space after a lone space, or any other whitespace token after a run, about +0.7;
   - a tab-containing whitespace token in the middle of a line (not right after a newline),
     about +1.5;
   - whitespace right after a digit, or right after the letter "n" of an escaped "\\n"
     inside a code string (indentation written as text), about +0.6.
   Whitespace right after a real newline (the start of a line) stays near 0.

Everything else is 0. The values are the mean activations of each class on training rows,
so the program is a small table of concepts, not a copy of the model.
"""

READS = ()

BLANK = set(" \t\xa0")  # whitespace tokens: spaces, tabs, no-break spaces


def _blank(s):
    return len(s) > 0 and all(ch in BLANK for ch in s)


def _lead_word(s):
    """A space followed by a word, e.g. ' the' or ' using'."""
    return len(s) > 1 and s[0] == " " and s[1:].isalpha()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]

    # First token of a document (or of the row): its activation depends on the token alone.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        if _lead_word(s):
            return None, -2.1
        if s.strip().isdigit() or not any(ch.isalnum() for ch in s):
            return None, 4.3
        return None, 2.0

    # Inside a document: whitespace runs and tabs.
    before = prefix.token_strings[-2]
    if _blank(s):
        if _blank(before):  # a later piece of an indentation run
            return None, 2.8 if (s == " " and len(before) > 1) else 0.7
        if before.endswith("\n"):  # start of a line: near zero
            return None, 0.0
        if "\t" in s:  # tab-indent mid-line
            return None, 1.5
        if before[-1:].isdigit() or before == "n":
            return None, 0.6
    return None, 0.0

programs.sol:
"""Signed lexical approximation dominated by electrical/electrochemical terms.

Recognize circuit parts and technical words split across tokens. Potential,
resistance and current get boosts from nearby physical vocabulary. Current
paths are positive; potential energy and electric-motion compounds are negative.
Small extra rules cover quantum states, cytotoxicity, quantity/data words and
a title-label colon. Magnitudes are rounded estimates from training activations.
This captures a vocabulary cluster, not every response of the component.
The short byte history resets at document boundaries.
"""
import re

READS = ()
ELECTRICAL = re.compile(
    r'electr|batter|capac|resist|diode|anode|cathode|conduct|volta|'
    r'circuit|ohm|coil|transistor|current|电|電|导|導|провод|ток')


def response(t, before):
    t, before = t.lower(), before.lower()
    token = t.strip()
    m = re.match(r'[^\W\d_]+', (before + t)[::-1])
    word = m.group()[::-1] if m else token
    physical = bool(ELECTRICAL.search(before[-100:]))
    value = 0.002
    if len(token) >= 2 and token[-1:].isalpha():
        if re.fullmatch(r'(inter)?electrodes?|anodes?|cathodes?|diodes?', word):
            value += 4.5
        elif re.fullmatch(r'(super|semi)conduct.*|induct(ance|or)?|conductors?', word):
            value += 3.2
        elif word == 'conductance':
            value += 1.9
        elif word in {'conduct', 'conducting', 'conductive', 'conductivity', 'resistance'}:
            value += 0.46 + 1.6 * physical
        elif re.fullmatch(r'batter(y|ies)', word):
            value += 1.85
        elif re.fullmatch(r'capac(it(ors?|ance|ive))?', word):
            value += 1.8
        elif re.fullmatch(r'resistors?|transist(ors?)?', word):
            value += 1.3
            if word.startswith('transist'):
                value += 1.65
        elif word in {'dielectric', 'photovolta', 'photovoltaic'}:
            value += 2.2
        elif word in {'potential', 'potentials'}:
            value += 1.0
            if re.search(r'electrode|membrane|action|formal', before[-55:]):
                value += 2.7
        elif word in {'current', 'currents', 'photocurrent'}:
            value += 0.3 * physical
            if word == 'photocurrent':
                value += 2.5
            if re.search((r'(tunneling|primary|neutron|electric|induced|alternating|direct|'
                          r'saturation|photo)\s*$'), before):
                value += 2.2
        elif word in {'voltage', 'voltages', 'capacit'}:
            value += 0.62
        elif word.endswith(('wire', 'wires')):
            value += 0.67
        elif word in {'circuit', 'circuits', 'switch', 'switches'}:
            value += 0.26 + 0.14 * physical
        elif word in {'cell', 'cells'}:
            if re.search(r'solar|electrochemical|half|fuel|load|memory', before[-35:]):
                value += 3.0
                if before.rstrip().endswith('solar'):
                    value += 0.85
        elif word in {'charge', 'charges', 'charged', 'charging', 'discharge'}:
            value += 0.18 + 0.51 * physical
            if before.rstrip().endswith('point'):
                value += 2.36
        elif word == 'energy':
            value -= 0.15
            if re.search(r'potential|electric', before[-30:]):
                value -= 2.25
        elif word in {'electricity', 'electrons', 'neutrons', 'neutron', 'propulsion'}:
            value -= 0.5
        elif word in {'through', 'across', 'between', 'flow'}:
            value += 0.33 * physical
            if word in {'through', 'across'} and re.search(
                    r'current|voltage|flux', before[-30:]):
                value += 2.74
        elif word in {'total', 'level', 'levels'}:
            value -= 0.2
            if word == 'total' and re.search(r'\ba\s*$', before):
                value -= 0.6
        elif word in {'data', 'param', 'parameter', 'parameters'}:
            value += 0.12
        elif word.startswith('cytotoxic'):
            value += 1.4
        elif word in {'junction', 'coupling', 'terminal', 'generator', 'antenna',
                      'sensing', 'sensor', 'transducer', 'synapses', 'dendrites'}:
            value += 0.4
        elif word == 'eigenstates':
            value += 2.25
        elif word in {'state', 'states'} and re.search(
                r'ground|excited|edge|superconducting', before[-25:]):
            value += 1.7
    if word == 'gap' and before.rstrip().endswith('band'):
        value += 5.8
    if token == '-type' and before.rstrip().endswith(('p', 'n')):
        value += 2.9
    # Russian conductor (провод), charge (заряд), and current (ток).
    if token == 'пров':
        value += 0.84
    elif token in {'од', 'ода'} and word.startswith('провод'):
        value += 3.36
    elif token in {'я', 'яда'} and word.startswith('заря'):
        value += 3.47
    elif token in {'ок', 'ока'} and word.startswith('ток'):
        value += 2.5
    # Battery, current, conductor, capacitor and voltage compounds.
    if token in {'电池', '電池', '储能'}:
        value += 1.71
    elif token == '池' and before.endswith(('电', '電')):
        value += 4.46
    elif token in {'电流', '電流', '电阻', '半导体', '半導体'}:
        value += 1.2
    elif token in {'线', '線'} and before.endswith(('导', '導')):
        value += 3.1
    elif token in {'导', '導'} and before.endswith(('半', '超', '电', '電')):
        value += 1.23
    elif token == '体' and before.endswith(('导', '導')):
        value += 3.39
    elif token in {'容', '壓', '压'} and before.endswith(('电', '電')):
        value += 3.1
    # Electric-motion words have the opposite sign.
    elif token in {'動', '动'} and before.endswith(('电', '電')):
        value -= 2.7
    if token == ':' and (before == 'title' or before.endswith('<|endoftext|>title')):
        value -= 4.67
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = b'' if first else carry[1]
    token = prefix.token_bytes[-1]
    value = response(token.decode('utf-8', errors='ignore'),
                     previous.decode('utf-8', errors='ignore'))
    return (doc, (previous + token)[-350:]), float(value + 0.07 * first)

"""Object-like pronouns, not full coreference resolution.

Lowercase English it/them get large values after transitive actions and
some prepositions; demonstratives get smaller values. Conjunctions and
likely noun-relative clauses lower the estimate. WordNet supplies word
classes and inflections. Romance verb-plus-object-clitic ending patterns
get a separate boost. The last 100 characters suffice for these local
heuristics; their state resets with each document. Other tokens get zero.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
LINKERS = set('''and but or nor yet so if unless when while because since
although though as that which who what where whether than then therefore
thus however hence'''.split())
AUXILIARIES = set('''am is are was were be been being can could will would
shall should may might must'''.split())
COMPLEMENT_VERBS = set('''say tell state report note indicate show suggest
imply mean ensure assume believe think know find see agree conclude
demonstrate prove confirm realize recognise recognize understand hope
expect suppose consider remember reveal explain mention observe notice'''.split())
TRANSITIVE_ACTIONS = set('''use fix handle execute consume share import export
edit change modify remove delete add implement apply process place put
fill overcome visit test run open close keep take extend translate convert
paste reproduce sanitize conceptualize read write view check set update
download store display draw pull throw'''.split())

# Columns: it, them, this/these, that.
# Prepositions are kept separate because 'in this' is usually a determiner
# phrase, while 'about it' and 'of them' commonly refer back to something.
PREPOSITIONS = {
    'of': (4.6, 3.1, 1.0, 1.4),
    'to': (3.0, 1.2, 1.0, 0.6),
    'for': (3.8, 1.8, 1.0, 1.4),
    'in': (2.2, 2.3, 0.1, 0.2),
    'on': (3.7, 3.2, 1.5, 1.4),
    'at': (6.4, 4.2, 0.5, 0.5),
    'with': (4.2, 3.2, 1.1, 1.5),
    'about': (6.1, 5.0, 2.6, 2.4),
    'from': (3.8, 2.1, 0.4, 0.5),
    'by': (2.5, 2.0, 0.3, 0.4),
    'like': (2.2, 2.8, 0.7, 1.6),
    'without': (3.8, 2.8, 1.3, 1.4),
}
DIRECTION = set('into onto through against toward towards'.split())
LOCATION = set('under over between among behind beside within'.split())
TIME = set('before after during until'.split())

@lru_cache(maxsize=10000)
def grammar_scores(word):
    if not word:
        return (-0.05, 1.5, 0.0, 0.0)
    if word in {'if','while','whether','since','when','though'}:
        return (0.5, 1.5, 0.4, 0.4)
    if word in LINKERS:
        return (0.0, 1.5, 0.0, 0.0)
    if word in AUXILIARIES:
        return (0.7, 0.8, 0.3, -0.1)
    if word in PREPOSITIONS:
        return PREPOSITIONS[word]
    if word in DIRECTION:
        return (4.2, 2.9, 1.1, 1.0)
    if word in LOCATION:
        return (3.2, 2.3, 0.3, 0.5)
    if word in TIME:
        return (0.6, 1.1, 0.3, 0.3)
    if word == 'how':
        return (1.5, 1.5, 1.2, 0.4)
    if word in {'typeof','new'}:
        return (0.0, 0.0, 0.0, 0.0)
    bases = set(wordnet.base_forms(word)) | {word}
    if word == 'return':
        return (4.8, 4.0, 0.1, 0.1)
    if 'do' in bases:
        if word == 'do':
            return (5.1, 5.0, 4.0, 4.4)
        return (2.6, 4.0, 1.5, 2.6)
    if 'have' in bases:
        return (4.3, 5.0, 3.0, 1.9)
    if 'make' in bases:
        return (1.6, 1.5, 2.1, 1.1)
    if bases & {'get','give'}:
        return (4.1, 2.2, 2.1, 1.1)
    if bases & TRANSITIVE_ACTIONS:
        strength = 6.2 if word in TRANSITIVE_ACTIONS else 4.9
        return (strength, 5.1, 2.3, 1.1)
    if bases & COMPLEMENT_VERBS:
        return (2.9, 3.0, 1.8, 0.3)
    pos = wordnet.parts_of_speech(word)
    if 'verb' in pos:
        return (4.3, 3.6, 1.7, 0.0)
    if not pos and word.endswith(('ing', 'ed')) and len(word) > 5:
        return (4.3, 3.6, 1.7, 0.0)
    if 'adjective' in pos:
        return (0.4, 1.7, -0.2, -0.2)
    if 'adverb' in pos:
        return (0.3, 1.7, 0.2, -0.2)
    return (0.1, 1.7, 0.0, -0.2)


def predict(token, word):
    if not token.startswith(' '):
        return 0.0
    t = token.strip()
    if t in {'it','them','this','these','those','that'}:
        scores = grammar_scores(word)
        if t == 'it':
            return scores[0]
        if t == 'them':
            return scores[1]
        if t == 'that':
            return scores[3]
        value = scores[2]
        if t == 'these':
            value = max(0.1, 0.9 * value + 0.15)
        if t == 'those':
            value = value if word == 'of' else max(0.1, 0.6 * value)
        return value
    return 0.0


# Spanish/Italian/Portuguese object clitics attached to an infinitive or
# gerund: hacer-lo, trovar-lo, utilizá-las, pensándo-lo. Splits can be
# inside either the verb ending or the clitic.
CLITIC_ENDING = re.compile(
    r"[a-zà-ÿ]{1,}(?:[aei]r|[aáeéií]ndo|[áéí])(?:-?l[oa]s?|l[ie])$",
    re.IGNORECASE,
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = ''
    if carry is not None and carry[0] == doc:
        previous = carry[1]
    token = prefix.token_strings[-1]
    match = re.search(r'([a-zA-Z]+)$', previous)
    word = match.group().lower() if match else ''
    value = predict(token, word)
    if token.strip() in {'it', 'this', 'that'} and match:
        before = previous[:match.start()]
        m2 = re.search(r'([a-zA-Z]+) $', before)
        # Whitespace is already part of the current pronoun token, so
        # the words preceding it end immediately before that token.
        if m2:
            w2 = m2.group(1).lower()
            # A determiner followed by a noun suggests a relative clause,
            # rather than a verb taking this pronoun as its object.
            if w2 in {'a', 'an', 'the', 'my', 'your', 'his', 'of'}:
                if not word.endswith('ing'):
                    if 'noun' in wordnet.parts_of_speech(word):
                        value = -0.1
            if word == 'at' and 'look' in wordnet.base_forms(w2):
                value = 5.0
    # A continuation token finishing a Romance verb+object clitic.
    if 0 < len(token) <= 5 and not token[0].isspace() and previous:
        if previous[-1].isalpha() or previous[-1] == '-':
            if CLITIC_ENDING.search((previous + token)[-45:]):
                value = 5.8
    return (doc, (previous + token)[-100:]), float(value)

"""Token-class pulse at each document or cropped-row start.

The pulse persists through an initial run of identical tokens. Bare definite articles,
code declarations, and some separator lines give large negative values;
initial letters and pronouns tend to be positive. Later text is nearly zero.
An initial numeric '12' (or '122') has a separate empirical negative pulse.
These are coarse lexical classes, not a token-by-token reconstruction.
"""
from functools import lru_cache
import wordnet

READS = ()
PREPOSITIONS = set('of in on at by for from with into about over under '
                   'through across between without during'.split())
PRONOUNS = set('i you he she it we they me him her us them who'.split())
AUXILIARIES = set('is are was were am be been being do does did have has '
                  'had can could will would shall should must may might'.split())
DECLARATIONS = set('import from class def function int char void public '
                   'private static const let var fn'.split())
MODULES = {'using', 'package', 'namespace'}
CONNECTIVES = set('if when since unless while although because'.split())


@lru_cache(maxsize=8192)
def onset(text):
    word = text.strip()
    lower = word.lower()
    spaced = text.startswith(' ')
    if text == '<|endoftext|>':
        return -7.2
    if lower == 'the':
        if not spaced:
            return -7.0 if word.isupper() else -12.5
        return -2.9 if word.istitle() else -4.5
    if not spaced and word in DECLARATIONS:
        return -11.2
    if not spaced and word in MODULES:
        return -5.65
    if not spaced and word == 'Using':
        return -6.5
    if word.startswith('#include'):
        return -5.0
    if word.startswith('#define'):
        return -9.8
    if not word:
        if text == ' ':
            return -1.08
        if text == '\n':
            return -0.33
        return -4.2 if text.count(' ') >= 3 else -1.7
    if text == '⎯':  # mathematical horizontal-line extender
        return -10.9
    if text.count('\n') == 1 and text.endswith('\n'):
        if word == '-':
            return -19.0
        if word and set(word) == {'|'}:
            return -15.5
        if word and set(word) == {'.'}:
            return -8.0
    if text.startswith('\\') and len(text) == 2:
        return -8.8  # two-character backslash escapes
    if word.isdecimal():
        return -2.39 if word == '0' else (0.64 if word == '1' else -0.6)
    if len(word) == 1 and word.isascii() and word.islower():
        return 0.7 if spaced else 0.0
    if len(word) == 1 and word.isupper():
        return 0.0 if word == 'A' else (1.6 if spaced else 2.7)
    if lower in CONNECTIVES:
        return -1.2 if spaced else -4.8
    if lower in PRONOUNS:
        return 2.1 if spaced else 0.8
    if lower in PREPOSITIONS:
        return -2.6 if spaced else -4.5
    if lower in AUXILIARIES:
        return -0.8 if spaced else -4.5
    if word and set(word) == {'#'}:
        return -3.3
    if word in {'-', '*', '+', '|', '•'}:
        return -2.2 if spaced else -5.0
    if word in {'(', ')', '[', ']', '"', "'"} and '\n' not in text:
        return 1.7
    if '\n' in text:
        return -2.0
    if word.isascii() and word.isalpha():
        pos = wordnet.parts_of_speech(lower)
        if 'verb' in pos or 'adjective' in pos or 'adverb' in pos:
            return -0.9 if spaced else -2.3
        return 0.1 if 'noun' in pos else -0.5
    return -0.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, 0)
    elif carry[2] and token != carry[1]:
        carry = (doc, carry[1], False, carry[3] + 1)
    else:
        carry = (*carry[:3], carry[3] + 1)
    value = onset(text) if carry[2] else -0.005
    # A large additional pulse occurs at the start of numeric text '12'.
    if carry[1] == b'1' and text == '2':
        if carry[3] == 1:
            value = -12.0
        elif carry[3] == 2 and prefix.token_strings[-2] == '2':
            value = -5.4
    return carry, value

programs.haiku:
"""Layer 1, MLP output channel 368 (`layers.1.mlp.down_proj:368`).

What it does: this component is silent inside a document and only speaks on the
document's first token (a row's first token, or the first token after a document break,
where attention and positions restart). That token alone decides the value, so the
component acts as a fixed per-word readout:

- "The" / "the" push strongly negative (about -12).
- " the" / " The" with a leading space push negative (about -4.4).
- Programming keywords and preprocessor words (import, package, class, def, int, public,
  #include, ...) push strongly negative (about -6.5).
- Other function words (of, in, on, is, when, what, ...) push mildly negative (about -1.8).
- Symbols and whitespace-only tokens push mildly negative (about -1).
- A single capital letter (I, N, S, M, ...) pushes positive (about +2.2).
- Everything else, and every non-first token, is about 0.

The program predicts these class values at each document start and 0 elsewhere.
"""

READS = ()

THE = {"The", "the"}
SPACE_THE = {" the", " The"}
CODE_WORDS = {
    "import", "package", "class", "def", "int", "void", "public", "private", "static",
    "using", "include", "function", "const", "var", "let", "typedef", "return", "double",
    "float", "bool", "long", "char", "struct", "namespace", "define", "ifndef", "export",
    "print", "type", "from", "#include", "#define", "#ifndef", "#import",
}
FUNCTION_WORDS = {
    "of", "in", "on", "at", "by", "for", "with", "from", "to", "is", "are", "was", "be",
    "if", "when", "what", "all", "not", "do", "one", "since", "let", "and", "or", "as",
    "a", "an", "this", "will", "can",
}


def value(s):
    """The activation for a document-first token `s` (its text decoded alone)."""
    word = s.strip()
    if s in THE:
        return -12.6
    if s in SPACE_THE:
        return -4.4
    if s in CODE_WORDS:
        return -6.5
    if word.lower() in FUNCTION_WORDS:
        return -1.8
    if len(word) == 1 and word.isupper():
        return 2.2
    if word and not any(ch.isalnum() for ch in word):
        return -1.0
    if word.isupper() is False and word[:1].isupper() and word[1:].islower():
        return -0.9
    return 0.0


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    starts_document = len(docs) == 1 or docs[-1] != docs[-2]
    if not starts_document:
        return carry, 0.0
    return carry, float(value(prefix.token_strings[-1]))

programs.sol:
"""Focus on the component's negative response to context-poor text openings.

Estimate the first token from its formatting and spelling shape. Continue
that estimate while the document merely repeats its first token; otherwise
predict zero (apart from a small carriage-return response). Bare comment
headers, control escapes and carriage returns have especially large values.
This omits the component's word-specific responses later in running text.
"""
import unicodedata

READS = ()


def opening_value(text):
    if text == '\r':
        return -2.4
    if text == '//\n':
        return -2.985
    if text == '<!':
        return -1.88
    if text in ('\\n', '\\t', '\\r', '\\"', "\\'"):
        return -2.2
    word = text.strip()
    if not word:
        if '\t' in text:
            return -0.64
        return -0.17 if '\n' in text else -0.30
    spaced = text.startswith(' ')
    if word.isascii() and word.isalpha():
        if word.isupper():
            return -0.46 if spaced else -0.76
        if spaced:
            return -0.40 if word.istitle() else -0.20
        return -0.30 if word.istitle() else -0.40
    if set(word) == {'·'}:
        return -0.85
    if not spaced and len(word) > 1:
        if all(unicodedata.category(ch)[0] in 'PS' for ch in word):
            return -0.50
    return -0.33


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_bytes[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        first, opening = token, True
    else:
        _, first, opening = carry
        opening = opening and token == first
    value = opening_value(text) if opening else 0.0
    if not opening and text == '\r':
        value = -0.05
    return (document, first, opening), value

"""Approximate closing attribute values and Chinese light-verb linkers.

A punctuation-only token closing a quoted HTML/XML attribute or a JSX
attribute expression receives a positive pulse. Closing a tool argument object
gets a smaller pulse, stronger if its opening is missing from this row.
Chinese light verbs and purpose markers receive separate
small pulses, with opposite signs when recent kana suggests Japanese instead.
Everything else is near zero except document-initial offsets and a negative
response to middle-dot leaders.
"""
import re

READS = ()

PERFORM = {'进行', '进行了', '進行'}
DO = {'作出', '做出', '做了', '作了'}
APPLY = {'予以', '加以'}
GIVE = {'给予', '給予'}
EXPAND = {'展开', '展開'}
KANA = re.compile(r'[\u3040-\u30ff]')
INSTRUMENT = re.compile(
    r'根据|根據|通过|通過|按照|凭借|憑藉|依據|依据|利用|使用|作為|作为|由'
    r'|方法|方式|手段|工具|标准|標準|(?<![可所])以(?!免|为|為)|用'
)
DIRECTION_OR_TIME = re.compile(r'[年历歷後后向原由归歸近而出起回前未下走]$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent = '' if first else carry[1]
    tool_open = False if first else carry[2]
    s = prefix.token_strings[-1]
    value = 0.0
    punct = s.strip().replace('\\"', '"')

    closing = punct.endswith(('"', "'", '}')) and not any(
        ch.isalnum() for ch in punct
    )
    if closing:
        before = recent.replace('\\"', '"').replace("\\'", "'")
        fragment = before.rsplit('<', 1)[-1] if '<' in before else ''
        fragment = fragment.replace('=>', '⇒')
        in_tag = bool(re.match(r'\??[A-Za-z][\w:.-]*(?:\s|$)', fragment))
        in_tag = in_tag and '>' not in fragment
        # HTML-style attributes also appear in wiki tables and templates.
        wiki = bool(re.search(r'\bstyle\s*=\s*"[^"<>]*$', before))
        template = '{%' in before and '%}' not in before.rsplit('{%', 1)[-1]
        context = fragment if in_tag else before
        if in_tag or wiki or template:
            end = punct[-1]
            if end in '\"\'' and '=' not in punct:
                pattern = (
                    r'(?<![=!<>])=\s*' + re.escape(end)
                    + '[^' + end + '<>]*$'
                )
                if re.search(pattern, context):
                    value = 6.0 if in_tag else 3.5
            elif end == '}' and in_tag:
                # Require the outermost attribute brace to close, not just
                # an inner object literal in an arrow function.
                expr = re.search(r'(\{[^<>]*)$', fragment)
                if expr:
                    body = expr.group(1)
                    depth = body.count('{') - body.count('}')
                    change = punct.count('{') - punct.count('}')
                    if depth > 0 and depth + change == 0:
                        value = 5.0

    # Escaped name=value assignments in quoted source or shell options can
    # occur without a visible tag around them.
    if closing and not value and punct.endswith('"') and '\\' in s:
        if re.search(r'[\w:-]+=\s*"[^"<>]*$', recent.replace('\\"', '"')):
            value = 3.5

    if '<tool_call>' in s:
        tool_open = True
    if '"}}' in s or s.strip() == '}}' and '\n' in s:
        value = max(value, 1.1 if tool_open else 3.3)
        tool_open = False

    japanese = bool(KANA.search(recent[-70:]))
    if s in PERFORM:
        value = -1.0 if japanese else 2.3
    elif s in DO:
        value = 1.5
    elif s in APPLY:
        value = 5.0
    elif s in GIVE:
        value = 1.0
    elif s in EXPAND:
        value = -1.0 if japanese else 1.0
    elif s in {'来', '來', '去'}:
        clause = re.split(r'[，。！？；\n]', recent[-80:])[-1]
        if japanese:
            value = -3.8 if s in {'来', '來'} else -0.8
        elif s in {'来', '來'} and DIRECTION_OR_TIME.search(recent.rstrip()):
            value = -1.8
        elif INSTRUMENT.search(clause):
            value = 3.7
        else:
            value = -0.4 if s in {'来', '來'} else 0.0
    elif s == '来进行':
        value = 4.8

    if first:
        value = -0.4
        if s.startswith(' ') and s.strip().isalpha() and s.isascii():
            value = -0.15
        elif not s.strip():
            value = -0.55
    if len(s) >= 2 and not s.strip('·'):
        value = -2.0
    return (doc, (recent + s)[-600:], tool_open), float(value)

programs.haiku:
"""Closing quote or brace of an attribute value in an HTML or JSX tag.

The program walks each row token by token and keeps a little state: whether it is
inside an opening tag (<name ...>), and whether it is inside an attribute value:
a quoted one (name="..." or name='...', or inside an escaped string name=\\"...\\")
or a JSX expression (name={...}). The component fires when such a value closes on a
bare token, a lone quote or brace (optionally with a backslash or newline). Merged
tokens such as ">, "></ and ">\\n do not fire.

Smaller rules, from the same data: the first token of each document is mildly
negative; the end of a JSON tool call ("}}\\n) is moderately positive; Chinese light
verbs that take a verbal-noun object (进行, 予以, 作出: carry out, give, make) are
positive; a run of middle dots (··) is strongly negative.
"""

READS = ()

# activation when an attribute value closes, by the closing token (backslash and
# trailing newline removed)
CLOSE = {'"': 6.0, "'": 6.0, "}": 7.5}
CLOSE_NEWLINE = {'"': 6.0, "'": 6.0, "}": 4.0}  # the same closers followed by a newline
DOC_START = -0.4  # first token of a document
JSON_END = 1.8    # end of a JSON tool call
VERB = {"进行": 2.2, "进行了": 2.3, "予以": 4.6, "作出": 1.9}
DOTS = -2.0       # the middle-dot run ··


def _scan(text, state):
    """Advance the tag/attribute state over one token's text; report if a value closed."""
    tag, attr, depth, prev = state
    closed = False
    for c in text:
        if attr in ('"', "'"):
            if c == attr:
                attr, closed = None, True
        elif attr == "{":
            if c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:
                    attr, closed = None, True
        elif tag:
            if c in ('"', "'") and prev == "=":
                attr = c
            elif c == "{" and prev == "=":
                attr, depth = "{", 1
            elif c == ">":
                tag = False
        elif c.isalpha() and prev == "<":
            tag = True
        if c != "\\":
            prev = c
    return (tag, attr, depth, prev), closed


def step(carry, prefix, upstream):
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        carry = (False, None, 0, "")
        return _scan(prefix.token_strings[-1], carry)[0], DOC_START
    tok = prefix.token_strings[-1]
    state, closed = _scan(tok, carry)
    if closed:
        bare = tok.replace("\\", "")
        if bare in CLOSE:
            return state, CLOSE[bare]
        if bare[:-1] in CLOSE_NEWLINE and bare.endswith("\n"):
            return state, CLOSE_NEWLINE[bare[:-1]]
    if tok == '"}}\n':
        return state, JSON_END
    if tok in VERB:
        return state, VERB[tok]
    if tok == "··":
        return state, DOTS
    return state, 0.0

programs.sol:
"""Code/text boundary markers, especially runs of repeated punctuation.

A run continuing from the preceding token is stronger than a fresh short
marker. Other positives are code fences, block comments, diff hunks,
heredocs and a few programming-language declaration markers. Finishing a
split UTF-8 mathematical/pictographic symbol is another positive. Stray
NULs after letters (as in misread UTF-16 text) also receive a large value.
A document-initial leader made of repeated middle dots is negative.
Other document starts get a small negative baseline.
Most other tokens are assigned zero; this is a partial, rule-based account.
"""
import re
import unicodedata
import regex

READS = ()
LARGE_OPERATORS = frozenset("∑∏∫∬∭∮")
EMOJI = regex.compile(r"\p{Emoji_Presentation}")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ""
        raw_tail = b""
        initial_dots = True
        first = True
    else:
        tail = carry[1]
        raw_tail = carry[2]
        initial_dots = carry[3]
        first = False
    s = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    t = s.strip()
    value = -0.15 if first else 0.0
    if tail and t and len(set(t)) == 1 and t[0] in "-=~_*+#/^─━═":
        c = t[0]
        n = len(t)
        previous = (len(tail) - len(tail.rstrip(c))) if s.startswith(c) else 0
        if previous and previous + n >= 4 and tail.strip(c):
            value = 1.05
        elif c in "-=" and n >= 3:
            value = min(0.9, 0.18 + 0.013 * n)
            if not s.startswith(" ") and tail[-1:] in ("'", '"'):
                value = 0.9
        elif c in "#*/_" and n >= 8:
            value = min(1.5, 0.15 + 0.021 * n)
        elif c == "^" and n >= 2 and tail.strip(c):
            value = 0.5
        elif c in "─━═":
            value = 0.75
    if initial_dots and len(s) >= 2 and set(s) == {"·"}:
        value = -2.4
    elif t == "_" and s.startswith(" "):
        value = 0.65 if tail.rstrip().endswith("_") else 0.15
    elif t == "\x00":
        if first:
            value = -3.4
        elif tail[-1:].isalpha():
            value = 1.4
        elif tail[-1:].isspace():
            value = 0.15
        else:
            value = 0.7
    elif t.startswith("```") or (t == "``" and tail.endswith("\n")):
        value = 1.0
    elif t == "`" and "\n" in s and s.startswith(" "):
        value = 0.7
    elif t.startswith("/**"):
        value = 0.65 if "\n" in s else 0.25
    elif t in ('"""', "'''") and "\n" in s:
        value = 0.45
    elif t == '#"':
        value = 0.95
    elif t == "</think>":
        value = 0.3
    elif t == "static" and tail.rstrip().endswith("import"):
        value = 0.95
    elif t == "@@":
        value = 0.95
    elif t == "EOF" and re.search(r"<<\s*['\"]?$", tail):
        value = 1.15
    elif (s == "namespace" and tail.endswith("\n")) or t == "@Override":
        value = 0.95
    elif t == "Override" and tail.endswith("@"):
        value = 0.55
    elif t == "once" and tail.endswith("#pragma"):
        value = 0.95
    elif t in ("int", "sum") and tail.endswith("\\"):
        value = 1.0
    elif s == "sum" and tail and not tail[-1].isalpha():
        value = 0.65
    elif t in {"else", "catch", "except"} and (
        tail.rstrip().endswith("}") or re.search(r"\n[ \t]*$", tail)
    ):
        value = 0.55
    elif t == "as" and tail.rstrip().endswith("*"):
        value = 1.0
    # Complete symbols and symbols split over byte-level tokens.
    c = t if len(t) == 1 else ""
    split = raw and 128 <= raw[0] < 192
    if split:
        c = (raw_tail + raw).decode("utf8", "replace")[-1]
    if c and ord(c) > 127:
        category = unicodedata.category(c)
        name = unicodedata.name(c, "")
        if c in LARGE_OPERATORS:
            value = 1.0
        elif "VARIATION SELECTOR" in name:
            value = 0.7
        elif name.startswith("MATHEMATICAL") and category[0] in "LN":
            value = 0.45
        elif split and category == "So" and c != "�":
            value = 0.65
        elif split and category == "Sm":
            value = 0.1
        elif c == "Σ" and tail.rstrip(" �").endswith("="):
            value = 0.8
        elif EMOJI.fullmatch(c):
            value = 0.6
    initial_dots = initial_dots and bool(s) and set(s) == {"·"}
    carry = (doc, (tail + s)[-100:], (raw_tail + raw)[-4:], initial_dots)
    return carry, value

"""Negative pulses at the end of name-like phrases and in definitions of them.

Capitalization, uncommon words, person senses, initials and honorifics provide
name evidence. Commas, parentheses, copulas and articles read that evidence;
parenthetical birth dates strengthen a biographical definition. Most other
positions are near zero. This is a heuristic, not a named-entity recognizer.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
WORDS = re.compile(r"[^\W\d_]+(?:[-’'][^\W\d_]+)*")
COPULA = re.compile(r'\b(is|was|were|are|became|becomes|been)\s*$')
HONORIFICS = {'Mr', 'Mrs', 'Ms', 'Dr', 'Prof', 'Sir', 'Dame', 'Lord',
              'Lady', 'Judge', 'President', 'Father', 'Saint', 'St'}
FUNCTION_WORDS = set('The A An In At By Of And But As For To With On From '
                     'After Before Not His Her Its Their My Our Your '
                     'This That These Those'.split())
COMMAS = {',', '，', '、', '،', ',"', ',\n', ',\n\n', '.,', '),', '),\n'}
OPEN_PARENS = {' (', '(', '（', ' （'}

@lru_cache(maxsize=30000)
def lexicon(word):
    return zipf_frequency(word.lower(), 'en'), wordnet.categories(word.lower())


def name_evidence(text):
    text = text.rstrip()
    copula = bool(COPULA.search(text))
    if copula:
        text = COPULA.sub('', text).rstrip()
    comma = text.endswith((',', '，', '、'))
    if comma:
        text = text[:-1].rstrip()
    parenthesis = re.search(r'\([^()]{0,180}\)\s*$', text)
    birth = bool(parenthesis and re.search(r'\d{4}|born|birth', parenthesis[0]))
    if parenthesis:
        text = text[:parenthesis.start()].rstrip()
    words = list(WORDS.finditer(text))
    if not words:
        return 0., copula, comma, birth, False, 0, False
    last = words[-1]
    word = last[0]
    gap = text[last.end():]
    capital = word[0].isupper() and gap in {'', '.', "'", '’', '"'}
    count = initials = 0
    honorific = False
    end = len(text)
    for match in reversed(words):
        w = match[0]
        separator = text[match.end():end]
        if (separator.strip(" .-’'") or not w[0].isupper()
                or w in FUNCTION_WORDS):
            break
        count += 1
        initials += len(w) == 1
        honorific |= w in HONORIFICS
        end = match.start()
    frequency, senses = lexicon(word)
    other = bool(senses and 'noun.person' not in senses)
    score = 0.
    if capital and not word.isupper():
        score = (.2 * (frequency < 5.5)
                 + .4 * ('noun.person' in senses)
                 + .5 * (not senses and frequency < 4.5)
                 + .5 * (count >= 2 and frequency < 5.5)
                 + .3 * (initials > 0 and frequency < 5.5)
                 + .2 * honorific)
    rare_subject = not capital and frequency < 3 and copula
    return max(0., score), copula, comma, birth, rare_subject, count, other


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, position = '', 0
    else:
        _, text, position = carry
    token = prefix.token_strings[-1]
    value = 0.
    relevant = (token in COMMAS or token in OPEN_PARENS or token in
                {' is', ' was', ' are', ' were', ' a', ' an', ' the',
                 ' ', ' et', ' v', ' Jr', ' Sr', '.'})
    if relevant:
        score, copula, comma, birth, rare, count, other = name_evidence(text)
        if token in COMMAS:
            value = -.025 - score
        elif token in OPEN_PARENS:
            value = -.09 - 1.14 * score
        elif token in {' is', ' was', ' are', ' were'}:
            value = -.66 * score - 1.38 * birth
        elif token in {' a', ' an'}:
            value = -.015
            if copula or comma:
                value -= 1.8 * score + 1.1 * birth + .7 * rare
        elif token == ' the':
            value = -.01 - (1.23 if comma else .6) * score
        elif token == ' ':
            value = -.013 - .49 * score * comma
        elif token in {' et', ' v'}:
            value = (-.5 if other else -1.7) if count else 0.
        elif token in {' Jr', ' Sr'}:
            value = -5.4 if count >= 2 else (-3.0 if count else 0.)
        # A generational suffix also affects its following punctuation.
        if re.search(r'\b(?:Jr|Sr)\.?[,]?$', text.rstrip()):
            if token == '.,':
                value = -3.2
            elif token == '.':
                value = -.8
            elif token == ' ' and comma:
                value = -2.5
    # A separate, very sharp response to the initial metadata label "Title:".
    if position <= 3 and text.strip() == 'Title' and token == ':':
        value = -12.86
    elif not text.strip() and token == 'Title':
        value = -.7
    return (doc, (text + token)[-300:], position + 1), float(value)

programs.haiku:
"""Layer-1 MLP component 372 (down_proj): a "who is this?" detector.

The component goes negative on the token right after a person's name, at the point where
the text is about to describe that person. Examples:
  "Doug Lowenstein[,] president of ..."     a comma after a name
  "Schiff[,] a pilot" at the start of a line  a one-word name at a line start, then a comma
  "Dave Fultz[ (]August 1..."                a parenthesis after a name
  "Ishaan Dev is[ an] Indian music ..."      the article after "is"/"was" after a name
  "Name (born 1938) is[ a] ..."              the same after a parenthetical date
  "Thomas Hillman[ Jr]."                     "Jr" (always) and "Sr"
  "Tsukagoshi[ et] al." / "al.[ (]2009"      "et" after a name, "(" after "et al."
Almost everywhere else the value is about 0.

Name-ness: the run of capitalised words directly before this token. Two or more words is
a name (a first and last name). One word counts only weakly, since sentence openers
("Today,") also match, unless it starts a line, which is how lists of people are written.

The predicted value is a table of weights in the component's activation units; the tables
below are least-squares fits on 2048 training rows.
"""

READS = ()

# Token right after a name -> (weight after one capitalised word, after two or more)
AFTER_NAME = {
    ",": (-0.35, -0.91),
    " (": (-0.61, -1.07),
    " et": (-1.72, -1.55),
    ".,": (-0.87, -0.89),
    " was": (-0.31, -0.61),
    " [": (-0.24, -0.30),
}
LINE_START_NAME_COMMA = -0.61  # "Schiff," at the start of a line
ARTICLE_AFTER_NAME_COMMA = (-0.32, -1.52)  # ", a pilot" / ", the founder" after a name
COPULA_ARTICLE = {"bio": -2.40, "name2": -1.41, "name1": -0.74, "other": -0.30}
ARTICLES = (" a", " an")
COPULAS = (" is", " was")
SENTENCE_END = (".", "?", "!", "\n", "<|endoftext|>")


def _starts_word(s):
    return s[:1] in (" ", "\n", "\t") or not s[:1].isalnum()


def _is_capitalised(word):
    return word.lstrip(" \n\t([\"“'‘«(")[:1].isupper()


def _name_run(strings, docs, t, limit=30):
    """(count, index of the run's first token) of the capitalised words ending just before
    token t, in this document. Initials like 'J.' do not break a name."""
    words = []  # (text, first token), nearest word first; built right to left
    word, start = "", t
    for j in range(t - 1, max(-1, t - limit - 1), -1):
        if docs[j] != docs[t]:
            break
        word = strings[j] + word
        start = j
        if _starts_word(strings[j]):  # this token begins the word
            words.append((word, start))
            word = ""
    if word:
        words.append((word, start))
    n, first = 0, t
    for w, j in words:
        if w.strip() in (".", ""):
            continue
        if not _is_capitalised(w):
            break
        n += 1
        first = j
    return n, first


def _closes_parenthesis(strings, docs, t, limit=30):
    """Whether a ')' closes a parenthesis earlier in the same sentence, before token t."""
    for j in range(t - 1, max(-1, t - limit - 1), -1):
        if docs[j] != docs[t] or strings[j].strip() in SENTENCE_END or "\n" in strings[j]:
            return False
        if strings[j].strip() == ")":
            return True
    return False


def _at_line_start(strings, docs, first):
    """Whether the token at `first` begins a line (or a document)."""
    if first == 0 or docs[first - 1] != docs[first]:
        return True
    return "\n" in strings[first - 1] or "endoftext" in strings[first - 1]


def step(carry, prefix, upstream):
    strings, docs, t = prefix.token_strings, prefix.document_ids, prefix.position
    if t == 0 or docs[t - 1] != docs[t]:
        return None, 0.0  # a document's first token: no name before it
    s, prev = strings[t], strings[t - 1]
    run, first = _name_run(strings, docs, t) if _starts_word(s) else (0, t)
    if s == " Jr":
        return None, -5.7
    if s == " Sr":
        return None, -2.5
    if s == " (" and t >= 2 and strings[t - 1] == "." and strings[t - 2].strip() == "al":
        return None, -2.8  # "et al. (2009)"
    if s in ARTICLES and prev in COPULAS:
        if _closes_parenthesis(strings, docs, t - 1):
            return None, COPULA_ARTICLE["bio"]  # "Name (born 1938) is a ..."
        before, _ = _name_run(strings, docs, t - 1)
        if before >= 2:
            return None, COPULA_ARTICLE["name2"]
        if before == 1:
            return None, COPULA_ARTICLE["name1"]
        return None, COPULA_ARTICLE["other"]
    if s in (" a", " an", " the") and prev == ",":
        before, _ = _name_run(strings, docs, t - 1)
        if before >= 1:
            one, many = ARTICLE_AFTER_NAME_COMMA
            return None, one if before == 1 else many
    if s in (" was", " is") and prev == ")":
        return None, -2.0 if s == " was" else -0.8
    if run >= 1 and s in AFTER_NAME:
        one, many = AFTER_NAME[s]
        if s == "," and run == 1 and _at_line_start(strings, docs, first):
            return None, LINE_START_NAME_COMMA
        return None, one if run == 1 else many
    return None, 0.0

programs.sol:
"""Token-local cues for consideration, assessment, and practical methods.

The largest positive responses mark Chinese 考虑 / 考慮 (consider), with
smaller responses to reviewing, estimating, observing, and circumstances.
A few two-character expressions cross token boundaries. File-opening syntax
is a separate response, restricted to the beginning of a document.
Unlisted tokens produce zero: small background and byte-fragment responses
are not reconstructed. This is lexical, not a passage-topic detector.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, previous = 0, ''
    else:
        _, age, previous = carry
    text = prefix.token_strings[-1]
    word = text.strip()
    value = 0.0

    if word in ('考虑', '考慮'):
        value = 3.6
    elif word == '要考虑':
        value = 4.0
    elif word == '考虑到':
        value = 1.6
    elif word in ('虑', '慮'):
        value = 2.6
        if previous.endswith('顧'):
            value = 4.3
        elif previous.endswith('疑'):
            value = 3.0
        elif previous.endswith('焦'):
            value = 2.0
    elif word == '考量':
        value = 1.5
    elif word in ('计', '計'):
        value = 0.5
        if previous.endswith(('预', '預', '算')):
            value = 1.5
        elif previous.endswith('共'):
            value = 2.0
        elif previous.endswith(('时', '時', '设', '設')):
            value = 0.0
    elif word == '量' and previous.endswith('思'):
        value = 2.5
    elif word == '討':
        value = 1.5 if previous.endswith('検') else 0.45
    elif word == '려' and previous.endswith('우'):
        value = 1.45  # 우려: concern
    elif word == '토' and previous.endswith('검'):
        value = 2.0  # 검토: review
    elif word in ('估计', '预计'):
        value = 0.9
    elif word in ('思考', '考えて'):
        value = 0.5
    elif word in ('办法', '辦法', '的办法', '采取'):
        value = 0.9
    elif word in ('情况', '的情况', '状况', '狀況'):
        value = 0.7
    elif word in ('察', '观察', '觀察'):
        value = 0.9
    elif word.lower() in ('consider', 'considered', 'consideration'):
        value = -0.16

    if age == 0:
        if word == 'Title':
            value = 1.06
        elif word == '<!':
            value = 5.4
        elif text.startswith('/*'):
            value = 1.4 if '\n' in text else 1.8
        elif word in ('"""', "'''"):
            value = 1.24
        elif word == 'def':
            value = 2.96
        elif word == 'int':
            value = 1.91
        elif word in ('import', 'package', 'using', 'class', '#include'):
            value = 0.55
        elif word in ('#', '##', '###'):
            value = 0.44
    elif age == 1 and previous == 'Title' and text == ':':
        value = 4.75
    return (doc, age + 1, text), value

programs.haiku:
"""Program v6: negative on code-vocabulary tokens (null/bool literals, type names,
comparison operators, library calls, empty call parentheses), scaled up when the
surrounding text is code-like and when the token follows code syntax."""
import re

READS = ()

NULL_LITERALS = {" nil", " null", " NULL", " None", " false", " False", " true", " True", "=True", "_TRUE",
                 " undefined"}
TYPE_NAMES = {" int", "int", "\tint", "(int", "<int", " String", "String", "(String", "<String", "[string",
              "string", " string", " str", "byte", " byte", " double", "double", "\tdouble", " float",
              "float", " boolean", "boolean", " void", "void", " uint", " char", " Integer", "Integer",
              " List", "[List", " HashMap", " ArrayList", " Exception", " InterruptedException",
              " IOException", "IOException", " PartialEq", " Promise", "Box"}
OPERATORS = {" !=", " !==", " ==", " ===", " else", " &&", " (!", " +=", " =>", " await"}
LIBRARY_CALLS = {".log", ".println", ".Println", ".Printf", ".printf", ".out", ".WriteLine", ".array",
                 ".arange", ".DataFrame", ".Series", ".pyplot", ".abs", ".substring", ".length",
                 ".stringify", ".isNotEmpty", "endl", "cout", "print", " print", "len", " len",
                 "isinstance", " isinstance", "strcpy", "strcmp", "assertTrue", " assertTrue",
                 "assertEquals", "_eq", "_modules", "stdlib", "@Override"}
EMPTY_CALLS = {"()", " ()", "().", "();\n", "()\n", "[]", " []", "[][]"}
CAMEL = re.compile(r"[a-z][A-Z]")
CODE_CHARS = re.compile(r"[{};()\[\]=<>]")
CODE_SYNTAX = {" !=", " ==", " ===", " return", "return", "\treturn", " public", "\tpublic", " private",
               " static", " final", " const", " new", " =", "(", "[", " ("}


def _weight(s):
    if s in NULL_LITERALS:
        return -1.3
    if s in TYPE_NAMES:
        return -1.0
    if s in OPERATORS:
        return -0.9
    if s in LIBRARY_CALLS:
        return -1.4
    if s in EMPTY_CALLS:
        return -0.8
    if CAMEL.search(s):
        return -0.4
    return 0.0


def step(carry, prefix, upstream):
    strs = prefix.token_strings
    docs = prefix.document_ids
    s = strs[-1]
    w = _weight(s)
    if w == 0.0:
        return carry, 0.0
    # recent text within the same document (last 24 tokens)
    start = max(0, len(strs) - 25)
    while start < len(strs) - 1 and docs[start] != docs[-1]:
        start += 1
    recent = strs[start:-1]
    dens = sum(1 for x in recent if CODE_CHARS.search(x)) / max(len(recent), 1)
    boost = 1.5 if len(strs) > 1 and strs[-2] in CODE_SYNTAX else 1.0
    return carry, float(w * boost * (0.5 + 2.0 * dens))

programs.sol:
"""Approximate two early lexical responses: groups, and short d fragments.

Collective nouns (audience, crowd, herd, Chinese 群) fire directly; 'of'
fires after a collective noun. Separately, incomplete ud/rd spellings fire,
especially after r or m, also in other alphabets. Strong Cyrillic cases
are люд- (people), труд- (work), серд- (heart). It assigns negative values
to d fragments after several Scandinavian accented vowels. Two document
header cases are included: Title's colon and an opening // comment line.
This is a spelling-and-local-phrase approximation, not a general d detector.
"""
import re
from anyascii import anyascii
import inflect

READS = ()

_english = inflect.engine()


def forms(words):
    """Singular and plural spellings of a small conceptual noun class."""
    singulars = set(words.split())
    return singulars | {_english.plural(w) for w in singulars}


GATHERINGS = forms('crowd herd audience')
GROUPS = forms('genus') | {'group', 'cluster', 'bundle'}
TEAMS = forms('team class suite cohort crew') | {
    _english.plural(w) for w in ('group', 'cluster')
}
COMMUNITIES = forms('family flock community army fleet')
COLLECTIONS = forms('set cup row band')


def predict(token, before, previous_word):
    s = token.strip().lower()
    b = before.lower()
    value = 0.0
    if s == 'of':
        if previous_word in GATHERINGS:
            value = 3.7
        elif previous_word in GROUPS:
            value = 2.5
        elif previous_word in TEAMS:
            value = 1.3
        elif previous_word in COMMUNITIES:
            value = .6
        elif previous_word in COLLECTIONS:
            value = .2
        elif previous_word in ('member', 'members', 'each'):
            value = -.25
    if s in ('audience', 'audiences', 'crowd', 'crowds'):
        value = 2.4 + (s.endswith('s'))
    elif s in ('herd', 'herds'):
        value = 4.8
    elif s.startswith('ience') and b.endswith('aud'):
        value = 7.0
    elif s == 'aud':
        value = .5
    if s.startswith('人群'):
        value = 4.5
    elif s == '群':
        value = 3.1
    elif s in ('群体', '族群', '群體'):
        value = 1.3

    # Ud at a token boundary, not buried inside a complete word like student.
    if re.fullmatch(r'(?:[a-z]?r?)ud(?:d|e|ed|y|der|a|ge|ging)?', s):
        leading = s.split('ud', 1)[0]
        left = leading or ('' if token[:1].isspace() else b)
        last = left[-1:]
        if s == 'aud':
            value = .5
        elif last == 'r':
            value = 4.8
        elif last == 'm':
            value = 3.7
        elif last == 'l':
            value = 2.6
        elif last in 'aeioujbt' and last:
            value = .25
        else:
            value = 1.3
        if len(s.split('ud', 1)[1]) > 1:
            value *= .65
        if s in ('udge', 'udging') and last not in ('j', 't'):
            value = 3.8
        if s == 'rude':
            value = 1.8
    if s in ('mud', 'crude', 'crud'):
        value = 3.8 if s != 'crud' else 5.0
    if s in ('erd', 'urd'):
        value = .8 if token[:1].isspace() else 2.7
    if (s.startswith('und') and b.endswith('r')
            and not token[:1].isspace()):
        value = 2.3
    other_alphabet = bool(s) and s[0] in 'дδد'
    d = anyascii(s) if other_alphabet else s
    left = anyascii(b[-8:]) if other_alphabet else b[-8:]
    if re.fullmatch(r'd[a-z]{0,3}', d) and not token[:1].isspace():
        if b.endswith('å'):
            value = -3.5
        elif b.endswith(('ä', 'ö', 'æ', 'ø', 'ő', 'j')):
            value = -1.8
        elif left.endswith(('her', 'ser')):
            value = 5.5
        elif left.endswith('crow'):
            value = 4.5
        elif left.endswith(('er', 'ur')):
            value = 2.4
        elif left.endswith(('ir', 'or')):
            value = 1.3
        elif left.endswith('r'):
            value = 2.0
        elif b.endswith('ü'):
            value = 2.5
        elif b[-1:].isdigit():
            value = -.7
    if s == 'уд':
        value = 2.5 if b.endswith(('ч', 'х', 'л', 'р', 'в')) else 1.1
    if s.startswith('д') and len(s) <= 3 and not token[:1].isspace():
        if b.endswith('лю'):
            value = 8.5 if s == 'д' else 3.4
        elif b.endswith('тру'):
            value = 8.0
        elif b.endswith('сер'):
            value = 6.5
        elif b.endswith('р'):
            value = 2.3
        elif b.endswith(('у', 'ю', 'ж', 'ъ')):
            value = 1.8
    if s in ('ям', 'ей', 'и') and b.endswith('люд'):
        value = 2.7
    if s == 'jd':
        value = -2.8
    if token == ':' and before == 'Title':
        value = 7.0
    if token == '//\n' and not before:
        value = -4.3
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    words = re.findall(r'[^\W\d_]+', before.lower())
    value = predict(token, before, words[-1] if words else '')
    return (document, (before + token)[-80:]), value

"""Approximate an 'on' detector and its row/document-opening effects.

Free prepositions ('on', 'upon', and some translations) are positive. Fixed
phrases about dependence, focus, or effect suppress that response. Separately,
opening tokens favor bare Latin fragments over frequent English words. A title
label at a document's start, and the GitHub domain, have strong extra responses.
Other positions default to zero; individual opening tokens are not memorized.
"""
import re
from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
ON_WORDS = {
    'on': 1.30, 'upon': 1.65, 'onto': 0.35,
    'sur': 1.35, 'på': 1.55, 'على': 1.18,
    'auf': 0.48, 'op': 0.67, 'na': 0.52,
}
# These expressions usually select 'on', rather than using it freely.
FIXED_ON = re.compile(
    r'\b(?:based|depends?|depending|dependent|focused|focus(?:es|ing)?|'
    r'concentrat(?:e|es|ed|ing)|effects?|impact|emphasis)'
    r'\s*(?:(?:\w+ly|only)\s*)?$', re.I,
)
RELY_ON = re.compile(r'\brel(?:y|ies|ied|ying)\s*$', re.I)


@lru_cache(maxsize=4096)
def opening_value(token):
    """A coarse word-frequency/word-boundary approximation at document start."""
    word = token.strip()
    if any(ch in '({[<_' for ch in word):
        return 2.0
    if word.isdigit():
        return -1.25
    if word in ('.', ',', ':', ';', '!', '?'):
        return -1.4
    frequency = zipf_frequency(word.lower(), 'en')
    spaced = token[:1].isspace()
    if frequency >= 7.4:
        return -3.0 if len(word) <= 2 else -1.9
    if frequency >= 5.4:
        return -1.3 if spaced else -0.5
    if spaced:
        return 0.75 if frequency < 3.2 else -1.3
    return 1.4 if regex.search(r'\p{Script=Latin}', word) else 0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = opening_value(token) if first else 0.0
    boundary = token[:1].isspace() or not previous or not previous[-1].isalpha()
    if not first and word in ON_WORDS and boundary:
        value = ON_WORDS[word]
        if word in ('on', 'upon'):
            if token.strip() == 'On':
                value = 1.04
            if FIXED_ON.search(previous):
                value = 0.16
            elif RELY_ON.search(previous):
                value = 0.32
            elif previous.lower().endswith(' so'):
                value = -0.5
    if first and word in ('on', 'upon'):
        value = 1.5
    if previous == 'Title' and token == ':':
        value = 18.3
    if token == '.com' and previous.lower().endswith('github'):
        value = 2.5
    return (doc, (previous + token)[-70:]), value

