"""Feature 376 of layers.1.mlp.down_proj (layer 1 MLP output), in plain terms.

Main behaviour: it reads the word "on". The component's activation is about +1 on the
preposition "on" (and its cousins "upon", "sur", "auf", "na", "på", "على"), but much weaker
when "on" follows an abstract dependence word ("based on", "depends on", "focus on",
"impact on", "rely on", "so on") and stronger after verbs of posting or placement
("played on", "listed on", "sitting on"). A domain suffix such as ".com" gives a weak positive.

First token of a document: with no context yet, the value depends only on the token. It
starts at +0.8, and drops for function words ("the", "of", "to", "that", "is"), for words
with a leading space (" Former", " of"), and for digits. These offsets come from a
least-squares fit on training data. This is a coarse approximation: the true value is a
fixed per-token number, and these few features capture only part of it.

Everything else is about 0. The program keeps no state, and it resets at each document start.
"""

READS = ()

ON_WORDS = {"on", "upon", "sur", "auf", "na", "på", "على"}
DEPENDENCE_WORDS = {
    "based", "focus", "focuses", "focused", "focusing", "depend", "depends", "depending",
    "dependent", "rely", "relies", "impact", "effect", "effects", "influence", "centered", "so",
}
POSTING_WORDS = {
    "played", "sitting", "sit", "sits", "listed", "filed", "appeared", "available", "released",
    "found", "located", "posted", "aired", "shown", "displayed", "served", "reported",
}
FUNCTION_WORDS = {
    "the", "of", "to", "and", "in", "is", "that", "was", "a", "an", "for", "with", "as", "by",
    "at", "from", "this", "it", "be", "are", "or", "which", "but", "not", "can", "has", "have",
    "will", "you", "we", "he", "she", "they", "its", "his", "her", "there", "their", "on",
}


def first_token_value(token):
    """Offset for the first token of a document, which has no context yet: a base level,
    lowered for function words, for words with a leading space, and for digits."""
    value = 0.8
    word = token.strip().lower()
    if word in FUNCTION_WORDS:
        value -= 1.1
    if token.startswith(" ") and word.isalpha():
        value -= 1.7
    if word[:1].isdigit():
        value -= 2.1
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, first_token_value(token)
    word = token.strip().lower()
    if word in ON_WORDS:
        previous = prefix.token_strings[-2].strip().lower()
        if previous in DEPENDENCE_WORDS:
            return None, 0.1
        if previous in POSTING_WORDS:
            return None, 2.0
        return None, 1.1
    if token in (".com", ".org", ".net"):
        return None, 0.6
    return None, 0.0

"""Activation predictor: the glyph o (any form) and digit 0."""
READS = ()

O_GLYPHS = set("oOöÖóÓòÒôÔõÕőŐωοоО0")
FUNCTION = set("of to for on from into or you your would one some should both also through how could".split())


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    core = s.strip()
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.6
    if s == "  ":
        return None, -1.9
    if len(core) == 1 and core in O_GLYPHS:
        return None, -1.5
    if core.lower() not in FUNCTION and any(c in O_GLYPHS for c in core):
        return None, -0.5
    if s == "\ufffd":
        return None, -0.5
    return None, 0.0

programs.sol:
"""A sparse, token-boundary-sensitive formatting-marker approximation.

Recognize script preambles, issue/title markup, publication prefixes,
ellipses and a few code/Markdown delimiters. Some document-openers have
large responses. Ordinary lexical responses are deliberately omitted.
Carry only document age and a short text tail; reset at document boundaries.
"""
import calendar
import re

READS = ()

# Literal spellings of code, markup and publication openers, at document start.
OPENERS = {
    '#!/': -0.24,
    '#include': 0.41,
    '#pragma': 1.06,
    '#ifndef': 0.73,
    '//': 0.57,
    '//\n': -0.80,
    '/*': 0.16,
    '/*\n': 0.39,
    '/*\r\n': 0.43,
    ' ///\n': 1.37,
    '<': 0.71,
    '<?': 0.52,
    'Pub': 1.48,
    'Published': 0.65,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, before = 0, ''
    else:
        _, age, before = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    value = OPENERS.get(token, 0.0) if age == 0 else 0.0

    # A shebang path, stronger when it opens the document.
    if token == '/env' and before.endswith('#!/usr/bin'):
        whole_marker = age >= 3 and prefix.token_strings[-4] == '#!/'
        value = 1.54 if age == 3 else (0.85 if whole_marker else 0.74)
    elif token == 'usr' and before.endswith('#!/'):
        whole_marker = prefix.token_strings[-2] == '#!/'
        value = 0.42 if age == 1 else (0.24 if whole_marker else 0.02)
    elif token == '/bin' and before.endswith('#!/usr'):
        value = 0.05 if age == 2 else 0.09
    elif token == '#include' and age > 0:
        value = 0.07

    # Structured issue headers and document-initial title labels.
    elif token == 'issue' and age == 4 and before == '<issue_start><':
        value = 2.32
    elif token == 'issue' and age == 1 and before == '<':
        value = 0.26
    elif token == ':' and age == 1 and before == 'Title':
        value = -1.90
    elif token == '>Title' and before.endswith('issue_comment'):
        value = -0.29

    # A line-leading ellipsis differs from inline dots and dot leaders.
    elif stripped and set(stripped) == {'.'} and len(stripped) >= 3:
        if '\n' in token:
            value = 0.08 if before.endswith('\n') else -0.01
        elif stripped == '...' and (not before or before.endswith('\n')):
            excerpt = re.search(r'\bpages\b', before, re.I)
            value = 0.70 if excerpt else 0.35
        else:
            value = -0.04 if token.startswith(' ') else -0.12
    elif re.fullmatch(r'\.{3,}\\+', token) and before.endswith('...'):
        value = 0.8
    elif '...' in token:
        value = -0.08

    # The "of" in ordinal dates; forum timestamps give the strongest case.
    elif token == ' of' and re.search(r'\d(?:st|nd|rd|th)$', before):
        weekday = any(day in before for day in calendar.day_name)
        if weekday:
            value = 0.47 if 'Posted:' in before else 0.22
        else:
            value = 0.05

    # Weaker typographic responses.
    elif len(stripped) >= 2 and set(stripped) == {'·'}:
        value = 0.44
    elif stripped in ('`', '``', '```'):
        if stripped == '```':
            value = -0.05
        elif stripped == '``':
            value = 0.04
    elif stripped in ('=>', '->', '-->', '→'):
        value = -0.10 if stripped == '=>' else -0.06
    elif stripped == '){':
        value = -0.02 if '\n' in token else -0.13
    elif stripped == '**':
        value = -0.04
    elif token == '  ':
        value = 0.035
    elif token == '   ':
        value = 0.015

    return (doc, age + 1, (before + token)[-160:]), value

"""Approximate a local formatting and collocation feature.

Positive responses mark separators after spaced reference numbers, chained
citations and adjacent parentheses. Page/minute suffixes can be negative.
There are also three lexical pairs and coarse document-initial defaults.
Unmodeled positions stay near zero.
These rules capture large observed responses, leaving token-specific variation
unexplained. A short text tail and the previous token reset per document.
"""
import re

READS = ()
NUMBER = re.compile(r'[0-9]+$')
CODE_STARTERS = {
    'int', 'string', 'char', 'float', 'double', 'void', 'bool',
    'def', 'class', 'import', 'using', 'struct', 'namespace',
    'public', 'private', 'const', 'static',
}
SEPARATORS = {' ', '\n', '\n\n', ' \n\n', ' |'}
PAGE_WORDS = {' pages', ' Pages'}


def initial_value(token):
    word = token.strip()
    if token.startswith('<|'):
        return -0.66
    if token.startswith(('//', '/*')):
        return -6.47 if word == '//' and '\n' in token else -1.05
    if word in CODE_STARTERS:
        return -1.03
    if token.isspace():
        return -0.50 if '\n' in token else -0.14
    if word.isdecimal() or not token.isascii():
        return -0.24
    if word.isalpha():
        return -0.40
    return -0.20


def advance(carry, token, document):
    first = carry is None or carry[0] != document
    if first:
        tail, previous, only_cr = '', '', True
    else:
        _, tail, previous, only_cr = carry
    state = (document, (tail + token)[-80:], token,
             only_cr and token == '\r')
    value = 0.001

    if token == '\r' and only_cr:
        value = -3.45
    elif first:
        value = initial_value(token)
    elif token == '能' and previous == '万':  # 万能: universal/all-purpose
        value = 7.8
    elif token.lstrip() in ('information', 'Information'):
        if previous == 'More':
            value = -4.0
        elif previous == ' More':
            value = -1.65
        elif previous == ' more':
            value = -0.52
    elif token == 'label' and previous.endswith('\\'):
        value = 0.56  # LaTeX \label
    elif token in (' (', '('):
        if previous.endswith(')'):
            if re.search(r'\([12][0-9]{3}\)$', tail):
                value = 2.65
            else:
                value = 1.20 if re.search(r'[0-9]+\)$', tail) else 0.48
        elif previous.endswith(']'):
            value = 0.30
    elif token in ('][', ')('):
        if previous[-1:].isdigit():
            repeated = token in tail[-8:]
            if token == '][':
                value = 0.71 if repeated else 0.31
            else:
                value = 0.76 if repeated else 0.11
        else:
            value = 0.09
    elif token in SEPARATORS or token in PAGE_WORDS or token in (' pp', ' min'):
        number = NUMBER.search(tail)
        n = len(number[0]) if number else 0
        before = tail[:number.start()] if number else tail
        line_is_number = not before.rsplit('\n', 1)[-1].strip()
        if token == ' ' and n:
            if before.endswith('  '):
                value = min(0.70, 0.25 * n)
            else:
                value = 0.015 * n if n < 4 else 0.015
        elif token == ' |' and n and line_is_number:
            value = 0.52
        elif token in SEPARATORS and '\n' in token and n and line_is_number:
            value = (0.0, 0.02, 0.18, 0.44, 0.20)[min(n, 4)]
        elif token == ' pp':
            if n:
                value = -4.5 if n >= 2 else -0.4
            else:
                value = -1.0 if previous.endswith(',') else -0.25
        elif token in PAGE_WORDS and n:
            value = -0.4 if n >= 2 else 0.05
        elif token == ' min':
            value = (0.1, 0.05, -0.2, -1.2)[min(n, 3)]
    return state, float(value)


def step(carry, prefix, upstream):
    return advance(carry, prefix.token_strings[-1], prefix.document_ids[-1])

"""A sparse, negative lexical detector; these motifs are not one semantic class.

The strongest rules recognize Chinese 首 (head/first), 彩 (color),
锦/錦 (brocade), and 采/採 (picking), plus a few color compounds.
Split UTF-8 characters get separate treatment.  Other rules recognize
Thai ศ and following pieces, short vowel-led continuations of 'sh',
placeholder email fragments, and repeated middle dots.  Everything else
gets 0.002.  State is just recent bytes and two tokens, reset by document.
This deliberately leaves most smaller and positive responses unexplained.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '', '')
    _, tail, previous, before_previous = carry
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'replace')
    joined = tail + raw
    whole = text
    fragmented = raw and 128 <= raw[0] < 192
    if fragmented:
        whole = joined.decode('utf-8', 'replace')[-1:]

    value = 0.002
    if whole in ('首', '彩', '锦', '錦'):
        value = -6.8 if fragmented else -5.3
    elif whole == '采':
        value = -3.9
    elif whole == '採':
        value = -1.2
    elif whole == '精彩':
        value = -4.6
    elif whole.endswith('首'):
        value = -3.3
    elif whole == '色彩':
        value = -1.5
    elif whole == '彩色':
        value = -3.3
    elif whole == '彩票':
        value = -0.5
    elif whole == '香' and fragmented:
        value = -1.9
    elif raw == b'\xa6' and tail.endswith(b'\xe9'):
        # An unfinished character in the UTF-8 neighborhood of 首 and 香.
        value = -6.1
    elif text == 'ศ':
        value = -3.8
    elif previous == 'ศ' and text:
        value = -1.2 if text == 'ึก' else -6.5
    elif before_previous == 'ศ' and previous == 'ิ' and text == 'ล':
        value = -7.0
    elif previous.strip().lower() == 'sh' and text[:1].islower():
        if len(text) <= 3 and text[0] == 'i':
            value = -1.1
        elif len(text) <= 3 and text[0] in 'aou':
            value = -0.55
        elif text[0] == 'ō':
            value = -1.0
    elif text in ('@example', '.lastname'):
        value = -1.2
    elif text and set(text) == {'·'} and len(text) > 1:
        value = -0.46
    return (doc, joined[-8:], text, previous), float(value)
